window.M3_BANK = {"meta": {"count": 112, "topics": {"3.01": {"en": "Electron theory", "el": "Θεωρία ηλεκτρονίων"}, "3.02": {"en": "Static electricity and conduction", "el": "Στατικός ηλεκτρισμός και αγωγή"}, "3.03": {"en": "Electrical terminology", "el": "Ηλεκτρική ορολογία"}, "3.04": {"en": "Generation of electricity", "el": "Παραγωγή ηλεκτρισμού"}, "3.05": {"en": "DC sources of electricity", "el": "Πηγές DC"}, "3.06": {"en": "DC circuits", "el": "Κυκλώματα DC"}, "3.07": {"en": "Resistance / resistor", "el": "Αντίσταση / αντιστάτης"}, "3.08": {"en": "Power", "el": "Ισχύς"}, "3.09": {"en": "Capacitance / capacitor", "el": "Χωρητικότητα / πυκνωτής"}, "3.10": {"en": "Magnetism", "el": "Μαγνητισμός"}, "3.11": {"en": "Inductance / inductor", "el": "Αυτεπαγωγή / πηνίο"}, "3.12": {"en": "DC motor / generator theory", "el": "Κινητήρες και γεννήτριες DC"}, "3.13": {"en": "AC theory", "el": "Θεωρία AC"}, "3.14": {"en": "R, C and L circuits", "el": "Κυκλώματα R, C, L"}, "3.15": {"en": "Transformers", "el": "Μετασχηματιστές"}, "3.16": {"en": "Filters", "el": "Φίλτρα"}, "3.17": {"en": "AC generators", "el": "Γεννήτριες AC"}, "3.18": {"en": "AC motors", "el": "Κινητήρες AC"}}, "exam": {"options": 3, "pass_mark": 0.75}}, "misc": {"octet_mixup": {"en": "8 is the limit of the second shell. Use 2n² with n = 3.", "el": "Το 8 είναι το όριο της δεύτερης στιβάδας. Χρησιμοποίησε 2n² με n = 3."}, "wrong_n": {"en": "Check which shell: n = 1, 2, 3 … then apply 2n².", "el": "Έλεγξε ποια στιβάδα: n = 1, 2, 3 … και μετά 2n²."}, "forgot_square": {"en": "The n is squared: 2n², not 2n.", "el": "Το n είναι στο τετράγωνο: 2n², όχι 2n."}, "ion_sign": {"en": "Losing negative electrons makes the atom positive (cation); gaining them makes it negative (anion).", "el": "Χάνοντας αρνητικά ηλεκτρόνια το άτομο γίνεται θετικό (κατιόν)· κερδίζοντας γίνεται αρνητικό (ανιόν)."}, "isotope_mixup": {"en": "Isotopes differ in neutrons, not electrons.", "el": "Τα ισότοπα διαφέρουν στα νετρόνια, όχι στα ηλεκτρόνια."}, "neutral_mixup": {"en": "A neutral atom has equal numbers of protons and electrons.", "el": "Ουδέτερο άτομο: ίσος αριθμός πρωτονίων και ηλεκτρονίων."}, "electron_mass": {"en": "Electrons are about 1/1836 of a proton's mass: they hardly count in the atom's mass.", "el": "Το ηλεκτρόνιο έχει περίπου το 1/1836 της μάζας του πρωτονίου: σχεδόν δεν μετράει στη μάζα του ατόμου."}, "coulomb_mixup": {"en": "6.24 × 10¹⁸ is the number of electrons in one coulomb, not a mass ratio.", "el": "Το 6,24 × 10¹⁸ είναι τα ηλεκτρόνια σε ένα coulomb, όχι λόγος μαζών."}, "full_shell": {"en": "A full outer shell holds its electrons tightly: that makes an insulator.", "el": "Πλήρης εξωτερική στιβάδα κρατά σφιχτά τα ηλεκτρόνια: αυτό κάνει έναν μονωτή."}, "neutron_mixup": {"en": "Neutrons carry no charge and do not carry current.", "el": "Τα νετρόνια δεν έχουν φορτίο και δεν μεταφέρουν ρεύμα."}, "ion_breakdown": {"en": "Ionization is any gain or loss of electrons; breakdown is the failure of an insulator in a strong field.", "el": "Ιοντισμός είναι κάθε κέρδος ή απώλεια ηλεκτρονίων· διάσπαση είναι η αστοχία μονωτή σε ισχυρό πεδίο."}, "atom_molecule": {"en": "A single atom of hydrogen or oxygen is not water.", "el": "Ένα άτομο υδρογόνου ή οξυγόνου δεν είναι νερό."}, "element_mixup": {"en": "Water is a compound of two elements, not an element.", "el": "Το νερό είναι ένωση δύο στοιχείων, όχι στοιχείο."}, "inner_shell": {"en": "Inner electrons are tightly bound and take no part in bonding.", "el": "Τα εσωτερικά ηλεκτρόνια είναι σφιχτά δεμένα και δεν συμμετέχουν στους δεσμούς."}, "nucleus_mixup": {"en": "There are no electrons in the nucleus: only protons and neutrons.", "el": "Στον πυρήνα δεν υπάρχουν ηλεκτρόνια: μόνο πρωτόνια και νετρόνια."}, "mass_weight": {"en": "kg is mass. Weight is a force, in newtons: W = m × g.", "el": "Τα kg είναι μάζα. Το βάρος είναι δύναμη, σε newton: W = m × g."}, "divided_g": {"en": "Multiply by g, do not divide.", "el": "Πολλαπλασίασε με το g, μη διαιρείς."}, "static_dynamic": {"en": "Charges flowing are dynamic electricity; static means charges at rest on a surface.", "el": "Φορτία σε ροή είναι δυναμικός ηλεκτρισμός· στατικός σημαίνει φορτία σε ηρεμία σε μια επιφάνεια."}, "conductor_leaks": {"en": "A conductor or a grounded surface lets the charge flow away, so nothing builds up.", "el": "Ένας αγωγός ή μια γειωμένη επιφάνεια αφήνει το φορτίο να φύγει, οπότε δεν συσσωρεύεται."}, "conservation": {"en": "Charge is conserved: what one material loses, the other gains.", "el": "Το φορτίο διατηρείται: ό,τι χάνει το ένα υλικό, το κερδίζει το άλλο."}, "like_unlike": {"en": "Like charges repel, unlike charges attract.", "el": "Ομώνυμα απωθούνται, ετερώνυμα έλκονται."}, "test_charge": {"en": "The convention uses a positive test charge. An electron moves against the field lines.", "el": "Η σύμβαση χρησιμοποιεί θετικό δοκιμαστικό φορτίο. Το ηλεκτρόνιο κινείται αντίθετα στις γραμμές."}, "field_strength": {"en": "Field strength is shown by how close the lines are, not by their length or arrows.", "el": "Η ένταση φαίνεται από την πυκνότητα των γραμμών, όχι από το μήκος ή τα βέλη."}, "outer_surface": {"en": "Excess charge on a conductor goes to the outer surface only.", "el": "Το επιπλέον φορτίο σε αγωγό πηγαίνει μόνο στην εξωτερική επιφάνεια."}, "sharp_points": {"en": "Charge concentrates where the curvature is tightest: at points and edges.", "el": "Το φορτίο συγκεντρώνεται όπου η καμπυλότητα είναι πιο έντονη: σε αιχμές και ακμές."}, "contact_induction": {"en": "Contact gives the same sign as the rod; induction with grounding gives the opposite sign.", "el": "Η επαφή δίνει το ίδιο πρόσημο με τη ράβδο· η επαγωγή με γείωση δίνει το αντίθετο."}, "ground_order": {"en": "If the ground is removed before the rod, the bar keeps its charge.", "el": "Αν η γείωση αφαιρεθεί πριν από τη ράβδο, η ράβδος κρατά το φορτίο της."}, "elementary_charge": {"en": "One electron carries only 1.6 × 10⁻¹⁹ C. A coulomb is 6.24 × 10¹⁸ electrons.", "el": "Ένα ηλεκτρόνιο έχει μόνο 1,6 × 10⁻¹⁹ C. Ένα coulomb είναι 6,24 × 10¹⁸ ηλεκτρόνια."}, "ohm_mixup": {"en": "Volts and ohms give a current (Ohm's law), not a charge. Charge = current × time.", "el": "Volt και ohm δίνουν ρεύμα (νόμος του Ohm), όχι φορτίο. Φορτίο = ρεύμα × χρόνος."}, "forgot_current": {"en": "That is the number for 1 C. Here Q = I × t = 2 C.", "el": "Αυτός είναι ο αριθμός για 1 C. Εδώ Q = I × t = 2 C."}, "inverted_e": {"en": "That is a charge in coulombs, not a number of electrons. Divide Q by e.", "el": "Αυτό είναι φορτίο σε coulomb, όχι αριθμός ηλεκτρονίων. Διαίρεσε το Q με το e."}, "forgot_square_d": {"en": "The distance is squared in Coulomb's law: F ∝ 1/d².", "el": "Η απόσταση είναι στο τετράγωνο στον νόμο του Coulomb: F ∝ 1/d²."}, "inverse_mixup": {"en": "Force goes up with the charges and down with the distance.", "el": "Η δύναμη αυξάνει με τα φορτία και μειώνεται με την απόσταση."}, "one_charge": {"en": "Both charges changed: multiply both factors, 2 × 2.", "el": "Άλλαξαν και τα δύο φορτία: πολλαπλασίασε και τους δύο παράγοντες, 2 × 2."}, "prefix_error": {"en": "Check the prefixes: µ = 10⁻⁶, m = 10⁻³.", "el": "Έλεγξε τα προθέματα: µ = 10⁻⁶, m = 10⁻³."}, "esd_pins": {"en": "Touching connector pins is exactly how ESD damage happens.", "el": "Το άγγιγμα των ακίδων είναι ακριβώς ο τρόπος που γίνεται η ζημιά από ESD."}, "esd_carpet": {"en": "Carpet builds up static charge: a known ESD source.", "el": "Η μοκέτα φορτίζεται στατικά: γνωστή πηγή ESD."}, "fuel_conductor": {"en": "Fuel is a poor conductor; that is why charge builds up in it.", "el": "Το καύσιμο είναι κακός αγωγός· γι' αυτό φορτίζεται."}, "metal_liquid": {"en": "Free electrons carry current in metals. In electrolytes the carriers are ions.", "el": "Τα ελεύθερα ηλεκτρόνια άγουν στα μέταλλα. Στους ηλεκτρολύτες φορείς είναι τα ιόντα."}, "nucleus_carrier": {"en": "Protons stay inside the nuclei; they are never free carriers here.", "el": "Τα πρωτόνια μένουν μέσα στους πυρήνες· δεν είναι ελεύθεροι φορείς."}, "gas_conductor": {"en": "Gases have almost no free carriers until they are ionized.", "el": "Τα αέρια σχεδόν δεν έχουν ελεύθερους φορείς μέχρι να ιονιστούν."}, "vacuum_ions": {"en": "There is nothing in a vacuum to ionize or cool; the electrons must be injected.", "el": "Στο κενό δεν υπάρχει τίποτα να ιονιστεί ή να ψυχθεί· τα ηλεκτρόνια πρέπει να εισαχθούν."}, "prefix_step": {"en": "Each prefix step (k, m, µ …) is a factor of 1 000. Count the steps.", "el": "Κάθε βήμα προθέματος (k, m, µ …) είναι παράγοντας 1 000. Μέτρα τα βήματα."}, "prefix_direction": {"en": "To a smaller unit the number gets bigger; to a bigger unit it gets smaller.", "el": "Σε μικρότερη μονάδα ο αριθμός μεγαλώνει· σε μεγαλύτερη μικραίνει."}, "mega_milli": {"en": "Capital M = mega (10⁶), small m = milli (10⁻³).", "el": "Κεφαλαίο M = mega (10⁶), μικρό m = milli (10⁻³)."}, "milli_micro": {"en": "milli = 10⁻³, micro = 10⁻⁶.", "el": "milli = 10⁻³, micro = 10⁻⁶."}, "charge_current": {"en": "Charge is an amount (C); current is how fast it flows (C/s).", "el": "Το φορτίο είναι ποσότητα (C)· το ρεύμα είναι πόσο γρήγορα ρέει (C/s)."}, "voltage_current": {"en": "Energy per coulomb is voltage, not current.", "el": "Η ενέργεια ανά coulomb είναι τάση, όχι ρεύμα."}, "multiplied": {"en": "You multiplied; this one needs a division.", "el": "Πολλαπλασίασες· εδώ χρειάζεται διαίρεση."}, "inverted": {"en": "The division is upside down. Check which quantity goes on top.", "el": "Η διαίρεση είναι ανάποδα. Έλεγξε ποιο μέγεθος πάει στον αριθμητή."}, "minutes": {"en": "Time must be in seconds: 1 min = 60 s.", "el": "Ο χρόνος σε δευτερόλεπτα: 1 min = 60 s."}, "ohm_inverse": {"en": "Ohms are for resistance; siemens are for conductance, its inverse.", "el": "Ohm για την αντίσταση· siemens για την αγωγιμότητα, το αντίστροφό της."}, "unit_mixup": {"en": "Check the unit: volts for potential difference, ohms for resistance, joules for energy.", "el": "Έλεγξε τη μονάδα: volt για τάση, ohm για αντίσταση, joule για ενέργεια."}, "absolute_potential": {"en": "Flow depends on the difference between the two points, not on either value alone.", "el": "Η ροή εξαρτάται από τη διαφορά μεταξύ των δύο σημείων, όχι από την καθεμιά τιμή."}, "resistance_emf": {"en": "Opposition to current is resistance. An emf is the push from a source.", "el": "Η αντίθεση στο ρεύμα είναι αντίσταση. Η ΗΕΔ είναι η ώθηση της πηγής."}, "coulomb_emf": {"en": "Despite the name, emf is not a force in newtons; it is measured in volts.", "el": "Παρά το όνομα, η ΗΕΔ δεν είναι δύναμη σε newton· μετριέται σε volt."}, "wire_drop": {"en": "Wires have almost no resistance, so almost no voltage drops along them.", "el": "Τα καλώδια δεν έχουν σχεδόν αντίσταση, οπότε σχεδόν δεν πέφτει τάση πάνω τους."}, "signal_speed": {"en": "The effect travels fast; the electrons themselves drift very slowly.", "el": "Το αποτέλεσμα διαδίδεται γρήγορα· τα ίδια τα ηλεκτρόνια κινούνται πολύ αργά."}, "inverse_calc": {"en": "G = 1 / R: divide 1 by the resistance.", "el": "G = 1 / R: διαίρεσε το 1 με την αντίσταση."}, "G_R_mixup": {"en": "Conductance is the inverse of resistance: more conductance, more current.", "el": "Η αγωγιμότητα είναι το αντίστροφο της αντίστασης: περισσότερη αγωγιμότητα, περισσότερο ρεύμα."}, "flow_direction": {"en": "Conventional current: + to −. Electron flow: − to +.", "el": "Συμβατική φορά: + προς −. Ροή ηλεκτρονίων: − προς +."}, "seven_list": {"en": "That one is in the list: light, heat, friction, pressure, chemical action, magnetism and motion.", "el": "Αυτό είναι στη λίστα: φως, θερμότητα, τριβή, πίεση, χημική δράση, μαγνητισμός και κίνηση."}, "source_mixup": {"en": "Match the energy to the device: light → photocell, heat → thermocouple, pressure → piezo crystal, chemical → battery.", "el": "Αντιστοίχισε ενέργεια και διάταξη: φως → φωτοκύτταρο, θερμότητα → θερμοζεύγος, πίεση → πιεζοκρύσταλλος, χημική → μπαταρία."}, "reverse_device": {"en": "That is the reverse process (a lamp or LED).", "el": "Αυτή είναι η αντίστροφη διαδικασία (λάμπα ή LED)."}, "hole_literal": {"en": "A hole is not a physical gap: it is a missing electron.", "el": "Η οπή δεν είναι φυσικό κενό: είναι ένα ηλεκτρόνιο που λείπει."}, "same_metals": {"en": "Identical metals give no thermoelectric voltage; the metals must be dissimilar.", "el": "Ίδια μέταλλα δεν δίνουν θερμοηλεκτρική τάση· πρέπει να είναι ανόμοια."}, "tc_absolute": {"en": "A thermocouple responds to the temperature difference between its junctions.", "el": "Το θερμοζεύγος αποκρίνεται στη διαφορά θερμοκρασίας των επαφών του."}, "tc_length": {"en": "Wire length does not set the emf; the metals and the temperature difference do.", "el": "Το μήκος δεν καθορίζει την ΗΕΔ· την καθορίζουν τα μέταλλα και η διαφορά θερμοκρασίας."}, "cht_egt": {"en": "Iron or copper with constantan: piston CHT. Chromel–alumel: turbine EGT.", "el": "Σίδηρος ή χαλκός με constantan: CHT εμβολοφόρων. Chromel–alumel: EGT στροβίλων."}, "tc_power": {"en": "Thermocouples, photocells and piezo crystals give tiny outputs: they are sensors, not power sources.", "el": "Θερμοζεύγη, φωτοκύτταρα και πιεζοκρύσταλλοι δίνουν μικρές εξόδους: είναι αισθητήρες, όχι πηγές ισχύος."}, "conductor_piezo": {"en": "Piezoelectric materials are insulating crystals, not metals.", "el": "Τα πιεζοηλεκτρικά υλικά είναι μονωτικοί κρύσταλλοι, όχι μέταλλα."}, "piezo_oneway": {"en": "The piezoelectric effect works both ways: stress → voltage and voltage → movement.", "el": "Το πιεζοηλεκτρικό φαινόμενο λειτουργεί και προς τις δύο κατευθύνσεις."}, "cell_sign": {"en": "The electrode that releases electrons collects them: it is the negative terminal.", "el": "Το ηλεκτρόδιο που απελευθερώνει ηλεκτρόνια τα συγκεντρώνει: είναι ο αρνητικός πόλος."}, "magnet_mixup": {"en": "Motion through flux induces an emf; it does not magnetize the conductor or change its resistance.", "el": "Η κίνηση μέσα σε ροή επάγει ΗΕΔ· δεν μαγνητίζει τον αγωγό ούτε αλλάζει την αντίστασή του."}, "parallel_flux": {"en": "Moving along the flux lines cuts no flux: no emf.", "el": "Κίνηση κατά μήκος των γραμμών δεν «κόβει» ροή: καμία ΗΕΔ."}, "stationary": {"en": "A conductor at rest in a steady field cuts no flux: no emf.", "el": "Ακίνητος αγωγός σε σταθερό πεδίο δεν «κόβει» ροή: καμία ΗΕΔ."}, "primary_secondary": {"en": "Rechargeable cells are secondary cells.", "el": "Τα επαναφορτιζόμενα στοιχεία είναι δευτερογενή."}, "dry_paste": {"en": "A dry cell has an electrolyte, as a moist paste.", "el": "Το ξηρό στοιχείο έχει ηλεκτρολύτη, σε μορφή υγρής πάστας."}, "dry_poles": {"en": "Carbon rod = positive, zinc case = negative.", "el": "Ράβδος άνθρακα = θετικός, περίβλημα ψευδαργύρου = αρνητικός."}, "alk_voltage": {"en": "Alkaline and carbon-zinc cells both give about 1.5 V; alkaline stores more energy.", "el": "Αλκαλικά και άνθρακα-ψευδαργύρου δίνουν και τα δύο ~1,5 V· το αλκαλικό αποθηκεύει περισσότερη ενέργεια."}, "plate_swap": {"en": "PbO₂ is positive, spongy lead is negative; discharge turns both into PbSO₄.", "el": "Το PbO₂ είναι θετικό, ο σπογγώδης μόλυβδος αρνητικός· η εκφόρτιση τα κάνει PbSO₄."}, "discharged_state": {"en": "Lead sulphate is what the plates become when discharged.", "el": "Θειικός μόλυβδος γίνονται οι πλάκες όταν εκφορτιστούν."}, "nicad_electrolyte": {"en": "KOH is the nickel-cadmium electrolyte. Lead-acid uses sulphuric acid.", "el": "Το KOH είναι ο ηλεκτρολύτης νικελίου-καδμίου. Η μπαταρία μολύβδου έχει θειικό οξύ."}, "sump_mixup": {"en": "Sodium bicarbonate is the neutralizer in the sump jar, not the electrolyte.", "el": "Το διττανθρακικό νάτριο είναι το εξουδετερωτικό στο sump, όχι ο ηλεκτρολύτης."}, "plate_count": {"en": "Each positive plate sits between two negatives: one extra negative plate.", "el": "Κάθε θετική πλάκα είναι ανάμεσα σε δύο αρνητικές: μία αρνητική παραπάνω."}, "separator_job": {"en": "Separators keep the plates apart; the acid is in the electrolyte.", "el": "Οι διαχωριστές κρατούν τις πλάκες χωριστά· το οξύ είναι στον ηλεκτρολύτη."}, "strap_job": {"en": "Cells are joined in series by cell straps, not separators.", "el": "Τα στοιχεία συνδέονται σε σειρά με γέφυρες (straps), όχι με διαχωριστές."}, "vent_job": {"en": "The vent plug only lets gas out and stops spills in inverted flight.", "el": "Η τάπα αφήνει μόνο τα αέρια να βγουν και αποτρέπει διαρροή σε ανάποδη πτήση."}, "sump_water": {"en": "Plain water would not neutralize the acid fumes.", "el": "Σκέτο νερό δεν θα εξουδετέρωνε τους όξινους ατμούς."}, "sg_direction": {"en": "Discharge uses acid and makes water: SG falls. Charging raises it.", "el": "Η εκφόρτιση καταναλώνει οξύ και παράγει νερό: το ειδικό βάρος πέφτει."}, "cell_count": {"en": "About 2 V per cell: 12 V = 6 cells, 24 V = 12 cells.", "el": "Περίπου 2 V ανά στοιχείο: 12 V = 6 στοιχεία, 24 V = 12 στοιχεία."}, "series_parallel": {"en": "Series adds voltages (same Ah); parallel adds Ah (same voltage).", "el": "Σε σειρά προστίθενται οι τάσεις (ίδιες Ah)· παράλληλα οι Ah (ίδια τάση)."}, "rating_time": {"en": "Aircraft batteries are rated at the 5-hour discharge rate.", "el": "Οι μπαταρίες αεροσκαφών βαθμονομούνται στον ρυθμό εκφόρτισης 5 ωρών."}, "capacity_rate": {"en": "Heavy currents heat the battery and reduce the Ah it can deliver.", "el": "Τα μεγάλα ρεύματα θερμαίνουν την μπαταρία και μειώνουν τις Ah που δίνει."}, "cycle_limit": {"en": "The end of cycle life is defined at 80% of rated capacity.", "el": "Το τέλος της ζωής σε κύκλους ορίζεται στο 80% της ονομαστικής χωρητικότητας."}, "test_tool": {"en": "A megger tests insulation resistance, not the state of charge.", "el": "Το megger μετρά αντίσταση μόνωσης, όχι κατάσταση φόρτισης."}, "float_scale": {"en": "A denser liquid lifts the float higher, so the biggest numbers are at the bottom of the stem.", "el": "Πυκνότερο υγρό ανεβάζει τον πλωτήρα, οπότε οι μεγάλοι αριθμοί είναι στο κάτω μέρος."}, "sg_band": {"en": "Bands: 1.300–1.275 high, 1.275–1.240 medium, 1.240–1.200 low.", "el": "Ζώνες: 1,300–1,275 υψηλή, 1,275–1,240 μέση, 1,240–1,200 χαμηλή."}, "temp_range": {"en": "No correction between 21 °C and 32 °C.", "el": "Καμία διόρθωση μεταξύ 21 °C και 32 °C."}, "water_timing": {"en": "Read before adding water: fresh water has not mixed and would give a false low reading.", "el": "Μέτρα πριν προσθέσεις νερό: το φρέσκο νερό δεν έχει αναμειχθεί και δίνει ψευδώς χαμηλή ένδειξη."}, "neutralizer": {"en": "Neutralize an acid with an alkali (bicarbonate); an alkali with a weak acid (vinegar, boric acid).", "el": "Οξύ εξουδετερώνεται με αλκαλικό (σόδα)· αλκαλικό με ασθενές οξύ (ξύδι, βορικό)."}, "rint_whole": {"en": "Use only the voltage drop (no-load minus load voltage), divided by the current.", "el": "Χρησιμοποίησε μόνο την πτώση τάσης (χωρίς φορτίο μείον με φορτίο), διά το ρεύμα."}, "rint_drop": {"en": "1.2 V is the drop itself, not the resistance. Divide it by the current.", "el": "Το 1,2 V είναι η πτώση, όχι η αντίσταση. Διαίρεσέ το με το ρεύμα."}, "charge_ir": {"en": "The charger must overcome the battery's emf plus its internal I × r drop.", "el": "Ο φορτιστής πρέπει να ξεπεράσει την ΗΕΔ της μπαταρίας και την εσωτερική πτώση I × r."}, "cv_cc": {"en": "Constant voltage: current tapers off (used on the aircraft). Constant current: current stays the same.", "el": "Σταθερή τάση: το ρεύμα μειώνεται (στο αεροσκάφος). Σταθερό ρεύμα: το ρεύμα μένει ίδιο."}, "vent_charge": {"en": "Loosen the caps so gas escapes, but leave them in place.", "el": "Χαλάρωσε τις τάπες για να βγαίνουν τα αέρια, αλλά άφησέ τες στη θέση τους."}, "inverse_g": {"en": "To get mass from weight, divide by g: m = W / g.", "el": "Για μάζα από βάρος, διαίρεσε με g: m = W / g."}, "mass_ratio": {"en": "The ratio is about 1836, not a small number.", "el": "Ο λόγος είναι περίπου 1836, όχι μικρός αριθμός."}, "ion_not_element": {"en": "Changing the electrons makes an ion of the same element; only the protons decide the element.", "el": "Αλλαγή στα ηλεκτρόνια δίνει ιόν του ίδιου στοιχείου· μόνο τα πρωτόνια καθορίζουν το στοιχείο."}, "valence_count": {"en": "6 is only the outer (valence) shell. A neutral atom has as many electrons as protons.", "el": "Το 6 είναι μόνο η εξωτερική στιβάδα. Ουδέτερο άτομο έχει τόσα ηλεκτρόνια όσα πρωτόνια."}, "square_mixup": {"en": "2n² means 2 × n × n, not (2n)² or n²: 2 × 16 = 32.", "el": "2n² σημαίνει 2 × n × n, όχι (2n)² ή n²: 2 × 16 = 32."}, "not_full": {"en": "A shell does not have to be full before the next one starts filling.", "el": "Μια στιβάδα δεν χρειάζεται να γεμίσει πριν αρχίσει να γεμίζει η επόμενη."}, "semi_mixup": {"en": "Silicon and germanium are semiconductors: between conductors and insulators.", "el": "Πυρίτιο και γερμάνιο είναι ημιαγωγοί: ανάμεσα σε αγωγούς και μονωτές."}}, "questions": [{"id": "L01-weight-si", "lesson": "L01", "topic": "3.01", "d": 1, "units": "SI", "q": {"en": "A 12 kg battery weighs (g = 9.81 m/s²):", "el": "Μπαταρία 12 kg έχει βάρος (g = 9,81 m/s²):"}, "o": [{"en": "1.22 N", "el": "1,22 N"}, {"en": "12 N", "el": "12 N"}, {"en": "118 N", "el": "118 N"}], "a": 2, "tags": ["divided_g", "mass_weight", null], "x": {"en": "W = m × g = 12 × 9.81 ≈ 118 N.", "el": "W = m × g = 12 × 9,81 ≈ 118 N."}, "status": "new"}, {"id": "L01-weight-imp", "lesson": "L01", "topic": "3.01", "d": 2, "units": "imperial", "q": {"en": "A component of mass 3 slugs weighs (g = 32.2 ft/s²):", "el": "Εξάρτημα μάζας 3 slugs έχει βάρος (g = 32,2 ft/s²):"}, "o": [{"en": "96.6 lbf", "el": "96,6 lbf"}, {"en": "10.7 lbf", "el": "10,7 lbf"}, {"en": "3 lbf", "el": "3 lbf"}], "a": 0, "tags": [null, "divided_g", "mass_weight"], "x": {"en": "W = m × g = 3 slug × 32.2 ft/s² = 96.6 lbf (1 lbf = 1 slug·ft/s²).", "el": "W = m × g = 3 slug × 32,2 ft/s² = 96,6 lbf (1 lbf = 1 slug·ft/s²)."}, "status": "new"}, {"id": "L01-mass-g", "lesson": "L01", "topic": "3.01", "d": 2, "units": "SI", "q": {"en": "An object weighs 49 N on Earth (g = 9.81 m/s²). Its mass is about:", "el": "Ένα σώμα ζυγίζει 49 N στη Γη (g = 9,81 m/s²). Η μάζα του είναι περίπου:"}, "o": [{"en": "481 kg", "el": "481 kg"}, {"en": "5 kg", "el": "5 kg"}, {"en": "49 kg", "el": "49 kg"}], "a": 1, "tags": ["inverse_g", null, "mass_weight"], "x": {"en": "m = W / g = 49 / 9.81 ≈ 5 kg.", "el": "m = W / g = 49 / 9,81 ≈ 5 kg."}, "status": "new"}, {"id": "L01-neutron-charge", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The neutron has:", "el": "Το νετρόνιο έχει:"}, "o": [{"en": "a positive charge", "el": "θετικό φορτίο"}, {"en": "no charge", "el": "μηδενικό φορτίο"}, {"en": "a negative charge", "el": "αρνητικό φορτίο"}], "a": 1, "tags": ["neutron_mixup", null, "neutron_mixup"], "x": {"en": "Neutrons are neutral; the proton is positive and the electron negative.", "el": "Το νετρόνιο είναι ουδέτερο· το πρωτόνιο θετικό, το ηλεκτρόνιο αρνητικό."}, "status": "new"}, {"id": "L01-nucleus", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The nucleus of an atom contains:", "el": "Ο πυρήνας του ατόμου περιέχει:"}, "o": [{"en": "protons and electrons", "el": "πρωτόνια και ηλεκτρόνια"}, {"en": "protons and neutrons", "el": "πρωτόνια και νετρόνια"}, {"en": "neutrons and electrons", "el": "νετρόνια και ηλεκτρόνια"}], "a": 1, "tags": ["nucleus_mixup", null, "nucleus_mixup"], "x": {"en": "Protons and neutrons form the nucleus; electrons are in shells around it.", "el": "Πρωτόνια και νετρόνια αποτελούν τον πυρήνα· τα ηλεκτρόνια είναι σε στιβάδες γύρω του."}, "status": "new"}, {"id": "L01-mass-ratio", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "A proton's mass is approximately how many times an electron's mass?", "el": "Η μάζα του πρωτονίου είναι περίπου πόσες φορές η μάζα του ηλεκτρονίου;"}, "o": [{"en": "1", "el": "1"}, {"en": "18", "el": "18"}, {"en": "1836", "el": "1836"}], "a": 2, "tags": ["electron_mass", "mass_ratio", null], "x": {"en": "m_p / m_e ≈ 1836. That is why electrons hardly count in an atom's mass.", "el": "m_p / m_e ≈ 1836. Γι' αυτό τα ηλεκτρόνια σχεδόν δεν μετράνε στη μάζα του ατόμου."}, "status": "new"}, {"id": "L01-element-protons", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "What decides which element an atom is?", "el": "Τι καθορίζει ποιο στοιχείο είναι ένα άτομο;"}, "o": [{"en": "The number of neutrons", "el": "Ο αριθμός νετρονίων"}, {"en": "The number of protons", "el": "Ο αριθμός πρωτονίων"}, {"en": "The number of electrons", "el": "Ο αριθμός ηλεκτρονίων"}], "a": 1, "tags": ["isotope_mixup", null, "ion_not_element"], "x": {"en": "The proton number (atomic number) defines the element. Changing neutrons gives an isotope; changing electrons gives an ion.", "el": "Ο αριθμός πρωτονίων (ατομικός αριθμός) ορίζει το στοιχείο. Άλλα νετρόνια δίνουν ισότοπο· άλλα ηλεκτρόνια δίνουν ιόν."}, "status": "new"}, {"id": "L01-oxygen-e", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "A neutral oxygen atom has 8 protons. How many electrons does it have?", "el": "Ουδέτερο άτομο οξυγόνου έχει 8 πρωτόνια. Πόσα ηλεκτρόνια έχει;"}, "o": [{"en": "6", "el": "6"}, {"en": "8", "el": "8"}, {"en": "16", "el": "16"}], "a": 1, "tags": ["valence_count", null, "neutral_mixup"], "x": {"en": "Neutral: electrons = protons = 8 (2 in the first shell, 6 in the second).", "el": "Ουδέτερο: ηλεκτρόνια = πρωτόνια = 8 (2 στην πρώτη στιβάδα, 6 στη δεύτερη)."}, "status": "new"}, {"id": "L01-compound", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Water (H₂O) is:", "el": "Το νερό (H₂O) είναι:"}, "o": [{"en": "an element", "el": "στοιχείο"}, {"en": "a compound", "el": "χημική ένωση"}, {"en": "an isotope", "el": "ισότοπο"}], "a": 1, "tags": ["element_mixup", null, "isotope_mixup"], "x": {"en": "Water is two elements, hydrogen and oxygen, chemically combined: a compound.", "el": "Το νερό είναι δύο στοιχεία, υδρογόνο και οξυγόνο, χημικά ενωμένα: χημική ένωση."}, "status": "new"}, {"id": "L01-molecule", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "The smallest particle of water that is still water is:", "el": "Το μικρότερο σωματίδιο νερού που είναι ακόμα νερό είναι:"}, "o": [{"en": "a hydrogen atom", "el": "ένα άτομο υδρογόνου"}, {"en": "a water molecule", "el": "ένα μόριο νερού"}, {"en": "an oxygen ion", "el": "ένα ιόν οξυγόνου"}], "a": 1, "tags": ["atom_molecule", null, "atom_molecule"], "x": {"en": "A molecule is the smallest particle that keeps the identity of the substance.", "el": "Το μόριο είναι το μικρότερο σωματίδιο που διατηρεί την ταυτότητα της ουσίας."}, "status": "new"}, {"id": "L01-shell3", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The maximum number of electrons in the third shell (n = 3) is:", "el": "Ο μέγιστος αριθμός ηλεκτρονίων στην τρίτη στιβάδα (n = 3) είναι:"}, "o": [{"en": "8", "el": "8"}, {"en": "18", "el": "18"}, {"en": "6", "el": "6"}], "a": 1, "tags": ["octet_mixup", null, "forgot_square"], "x": {"en": "2n² = 2 × 3² = 18.", "el": "2n² = 2 × 3² = 18."}, "status": "new"}, {"id": "L01-shell4", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "Using 2n², the fourth shell can hold at most:", "el": "Με τον τύπο 2n², η τέταρτη στιβάδα χωρά το πολύ:"}, "o": [{"en": "8 electrons", "el": "8 ηλεκτρόνια"}, {"en": "16 electrons", "el": "16 ηλεκτρόνια"}, {"en": "32 electrons", "el": "32 ηλεκτρόνια"}], "a": 2, "tags": ["wrong_n", "square_mixup", null], "x": {"en": "2n² = 2 × 4² = 2 × 16 = 32.", "el": "2n² = 2 × 4² = 2 × 16 = 32."}, "status": "new"}, {"id": "L01-fill-order", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "Electron shells fill:", "el": "Οι στιβάδες γεμίζουν:"}, "o": [{"en": "from the shell nearest the nucleus outwards", "el": "από τη στιβάδα πιο κοντά στον πυρήνα προς τα έξω"}, {"en": "from the outermost shell inwards", "el": "από την εξωτερική στιβάδα προς τα μέσα"}, {"en": "only after the previous shell is completely full", "el": "μόνο αφού γεμίσει εντελώς η προηγούμενη"}], "a": 0, "tags": [null, "inner_shell", "not_full"], "x": {"en": "The innermost shell has the lowest energy and fills first, but a shell need not be full before the next one starts.", "el": "Η εσωτερική στιβάδα έχει τη χαμηλότερη ενέργεια και γεμίζει πρώτη, αλλά μια στιβάδα δεν χρειάζεται να γεμίσει πριν ξεκινήσει η επόμενη."}, "status": "new"}, {"id": "L01-valence", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Valence electrons are the electrons:", "el": "Ηλεκτρόνια σθένους είναι τα ηλεκτρόνια:"}, "o": [{"en": "in the outermost shell", "el": "της εξωτερικής στιβάδας"}, {"en": "in the innermost shell", "el": "της εσωτερικής στιβάδας"}, {"en": "inside the nucleus", "el": "μέσα στον πυρήνα"}], "a": 0, "tags": [null, "inner_shell", "nucleus_mixup"], "x": {"en": "Valence electrons are in the outer shell and take part in bonding.", "el": "Τα ηλεκτρόνια σθένους είναι στην εξωτερική στιβάδα και συμμετέχουν στους δεσμούς."}, "status": "new"}, {"id": "L01-cation", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "An atom that loses an electron becomes:", "el": "Ένα άτομο που χάνει ένα ηλεκτρόνιο γίνεται:"}, "o": [{"en": "a negative ion (anion)", "el": "αρνητικό ιόν (ανιόν)"}, {"en": "a positive ion (cation)", "el": "θετικό ιόν (κατιόν)"}, {"en": "an isotope", "el": "ισότοπο"}], "a": 1, "tags": ["ion_sign", null, "isotope_mixup"], "x": {"en": "It now has more protons than electrons, so it is positive: a cation.", "el": "Έχει πλέον περισσότερα πρωτόνια από ηλεκτρόνια, άρα είναι θετικό: κατιόν."}, "status": "new"}, {"id": "L01-ion-charge", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "An atom has 11 protons and 10 electrons. It is:", "el": "Ένα άτομο έχει 11 πρωτόνια και 10 ηλεκτρόνια. Είναι:"}, "o": [{"en": "neutral", "el": "ουδέτερο"}, {"en": "a positive ion, charge +1", "el": "θετικό ιόν, φορτίο +1"}, {"en": "a negative ion, charge −1", "el": "αρνητικό ιόν, φορτίο −1"}], "a": 1, "tags": ["neutral_mixup", null, "ion_sign"], "x": {"en": "Net charge = 11 − 10 = +1 elementary charge: a cation.", "el": "Καθαρό φορτίο = 11 − 10 = +1 στοιχειώδες φορτίο: κατιόν."}, "status": "new"}, {"id": "L01-free-e", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "The current in a metal wire is the flow of:", "el": "Το ρεύμα σε μεταλλικό σύρμα είναι ροή:"}, "o": [{"en": "free electrons", "el": "ελεύθερων ηλεκτρονίων"}, {"en": "protons", "el": "πρωτονίων"}, {"en": "neutrons", "el": "νετρονίων"}], "a": 0, "tags": [null, "nucleus_carrier", "neutron_mixup"], "x": {"en": "Loosely bound outer electrons drift from atom to atom; the nuclei stay in place.", "el": "Τα χαλαρά δεμένα εξωτερικά ηλεκτρόνια κινούνται από άτομο σε άτομο· οι πυρήνες μένουν στη θέση τους."}, "status": "new"}, {"id": "L01-conductor", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Which is the best conductor?", "el": "Ποιος είναι ο καλύτερος αγωγός;"}, "o": [{"en": "Silver", "el": "Άργυρος"}, {"en": "Germanium", "el": "Γερμάνιο"}, {"en": "Glass", "el": "Γυαλί"}], "a": 0, "tags": [null, "semi_mixup", "full_shell"], "x": {"en": "Silver (like copper and gold) has one loose valence electron and many free electrons.", "el": "Ο άργυρος (όπως ο χαλκός και ο χρυσός) έχει ένα χαλαρό ηλεκτρόνιο σθένους και πολλά ελεύθερα ηλεκτρόνια."}, "status": "new"}, {"id": "L01-semi", "lesson": "L01", "topic": "3.01", "d": 1, "units": "—", "q": {"en": "Silicon and germanium are:", "el": "Το πυρίτιο και το γερμάνιο είναι:"}, "o": [{"en": "conductors", "el": "αγωγοί"}, {"en": "insulators", "el": "μονωτές"}, {"en": "semiconductors", "el": "ημιαγωγοί"}], "a": 2, "tags": ["semi_mixup", "semi_mixup", null], "x": {"en": "They are the common semiconductor materials used in transistors and chips.", "el": "Είναι τα συνηθισμένα υλικά ημιαγωγών, για τρανζίστορ και chips."}, "status": "new"}, {"id": "L01-breakdown", "lesson": "L01", "topic": "3.01", "d": 2, "units": "—", "q": {"en": "When a very strong electric field tears electrons loose in an insulator, this is called:", "el": "Όταν πολύ ισχυρό ηλεκτρικό πεδίο αποσπά ηλεκτρόνια σε έναν μονωτή, αυτό λέγεται:"}, "o": [{"en": "ionization of the conductor", "el": "ιονισμός του αγωγού"}, {"en": "breakdown", "el": "διάσπαση (breakdown)"}, {"en": "valence bonding", "el": "δεσμός σθένους"}], "a": 1, "tags": ["ion_breakdown", null, "inner_shell"], "x": {"en": "Breakdown: the insulator starts to conduct and is usually damaged.", "el": "Διάσπαση: ο μονωτής αρχίζει να άγει και συνήθως καταστρέφεται."}, "status": "new"}, {"id": "L02-static", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Static electricity is:", "el": "Ο στατικός ηλεκτρισμός είναι:"}, "o": [{"en": "a build-up of charge on the surface of an object", "el": "συσσώρευση φορτίου στην επιφάνεια ενός σώματος"}, {"en": "a steady flow of electrons in a closed circuit", "el": "σταθερή ροή ηλεκτρονίων σε κλειστό κύκλωμα"}, {"en": "the current produced by a battery", "el": "το ρεύμα που δίνει μια μπαταρία"}], "a": 0, "tags": [null, "static_dynamic", "static_dynamic"], "x": {"en": "Static: charges at rest, piled up on a surface. A flow of electrons is dynamic electricity.", "el": "Στατικός: φορτία σε ηρεμία, συσσωρευμένα σε μια επιφάνεια. Η ροή ηλεκτρονίων είναι δυναμικός ηλεκτρισμός."}, "status": "new"}, {"id": "L02-insulator", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "A static charge builds up when two surfaces touch and separate and at least one of them is:", "el": "Στατικό φορτίο δημιουργείται όταν δύο επιφάνειες έρθουν σε επαφή και απομακρυνθούν, και τουλάχιστον η μία είναι:"}, "o": [{"en": "a conductor", "el": "αγωγός"}, {"en": "an insulator", "el": "μονωτής"}, {"en": "grounded", "el": "γειωμένη"}], "a": 1, "tags": ["conductor_leaks", null, "conductor_leaks"], "x": {"en": "An insulator cannot let the extra charge flow away, so the imbalance stays.", "el": "Ο μονωτής δεν αφήνει το επιπλέον φορτίο να φύγει, οπότε η ανισορροπία παραμένει."}, "status": "new"}, {"id": "L02-tribo", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "In the triboelectric effect, the material that loses electrons becomes:", "el": "Στο τριβοηλεκτρικό φαινόμενο, το υλικό που χάνει ηλεκτρόνια γίνεται:"}, "o": [{"en": "negative", "el": "αρνητικό"}, {"en": "positive", "el": "θετικό"}, {"en": "neutral", "el": "ουδέτερο"}], "a": 1, "tags": ["ion_sign", null, "conservation"], "x": {"en": "Losing negative electrons leaves more protons than electrons: positive.", "el": "Χάνοντας αρνητικά ηλεκτρόνια μένουν περισσότερα πρωτόνια: θετικό."}, "status": "new"}, {"id": "L02-fur", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A plastic rod is rubbed with fur. The plastic becomes negative. The fur becomes:", "el": "Πλαστική ράβδος τρίβεται με γούνα και η ράβδος φορτίζεται αρνητικά. Η γούνα γίνεται:"}, "o": [{"en": "positive, with the same amount of charge", "el": "θετική, με ίσο ποσό φορτίου"}, {"en": "negative as well", "el": "επίσης αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 0, "tags": [null, "conservation", "conservation"], "x": {"en": "Charge is conserved: the electrons the plastic gained came from the fur.", "el": "Το φορτίο διατηρείται: τα ηλεκτρόνια που κέρδισε το πλαστικό ήρθαν από τη γούνα."}, "status": "new"}, {"id": "L02-likes", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Two pith balls touched by the same positively charged glass rod will:", "el": "Δύο σφαιρίδια που ακουμπήθηκαν από την ίδια θετικά φορτισμένη γυάλινη ράβδο θα:"}, "o": [{"en": "attract each other", "el": "έλκονται"}, {"en": "repel each other", "el": "απωθούνται"}, {"en": "not affect each other", "el": "δεν αλληλεπιδρούν"}], "a": 1, "tags": ["like_unlike", null, "like_unlike"], "x": {"en": "Both get the same (positive) charge. Like charges repel.", "el": "Παίρνουν και τα δύο θετικό φορτίο. Ομώνυμα φορτία απωθούνται."}, "status": "new"}, {"id": "L02-fielddir", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "The direction of an electric field line is the direction in which:", "el": "Η φορά μιας δυναμικής γραμμής ηλεκτρικού πεδίου είναι η φορά προς την οποία:"}, "o": [{"en": "an electron would move", "el": "θα κινούνταν ένα ηλεκτρόνιο"}, {"en": "a small positive test charge would move", "el": "θα κινούνταν ένα μικρό θετικό δοκιμαστικό φορτίο"}, {"en": "the field gets weaker", "el": "το πεδίο εξασθενεί"}], "a": 1, "tags": ["test_charge", null, "field_strength"], "x": {"en": "By convention a positive test charge sets the direction: away from + and into −.", "el": "Κατά σύμβαση τη φορά την ορίζει θετικό δοκιμαστικό φορτίο: από το + προς το −."}, "status": "new"}, {"id": "L02-density", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "On a field-line drawing, the strength of the field is shown by:", "el": "Σε ένα σχέδιο δυναμικών γραμμών, η ένταση του πεδίου φαίνεται από:"}, "o": [{"en": "the length of the lines", "el": "το μήκος των γραμμών"}, {"en": "the number of lines per unit area", "el": "τον αριθμό γραμμών ανά μονάδα επιφάνειας"}, {"en": "the direction of the arrowheads", "el": "τη φορά των βελών"}], "a": 1, "tags": ["field_strength", null, "field_strength"], "x": {"en": "Closely spaced lines mean a strong field; arrows only show the direction.", "el": "Πυκνές γραμμές σημαίνουν ισχυρό πεδίο· τα βέλη δείχνουν μόνο τη φορά."}, "status": "new"}, {"id": "L02-hollow", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A hollow metal sphere is charged. The excess charge is found:", "el": "Μια κούφια μεταλλική σφαίρα φορτίζεται. Το επιπλέον φορτίο βρίσκεται:"}, "o": [{"en": "evenly on the inner and outer surfaces", "el": "ομοιόμορφα στην εσωτερική και την εξωτερική επιφάνεια"}, {"en": "only on the outer surface", "el": "μόνο στην εξωτερική επιφάνεια"}, {"en": "only on the inner surface", "el": "μόνο στην εσωτερική επιφάνεια"}], "a": 1, "tags": ["outer_surface", null, "outer_surface"], "x": {"en": "Like charges push as far apart as possible: all of it goes to the outside. The inside is neutral and field-free.", "el": "Τα ομώνυμα φορτία απομακρύνονται όσο γίνεται: όλο το φορτίο πάει έξω. Το εσωτερικό είναι ουδέτερο και χωρίς πεδίο."}, "status": "new"}, {"id": "L02-points", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "On an irregularly shaped charged conductor, the charge is most concentrated:", "el": "Σε αγωγό ακανόνιστου σχήματος, το φορτίο είναι πιο συγκεντρωμένο:"}, "o": [{"en": "on the flattest areas", "el": "στις πιο επίπεδες περιοχές"}, {"en": "at the points and sharp edges", "el": "στις αιχμές και τις οξείες ακμές"}, {"en": "evenly everywhere", "el": "ομοιόμορφα παντού"}], "a": 1, "tags": ["sharp_points", null, "sharp_points"], "x": {"en": "The tighter the curvature, the more charge per area and the stronger the field. That is why static wicks are pointed.", "el": "Όσο πιο έντονη η καμπυλότητα, τόσο περισσότερο φορτίο ανά επιφάνεια και ισχυρότερο πεδίο. Γι' αυτό τα static wicks είναι μυτερά."}, "status": "new"}, {"id": "L02-induction", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A neutral metal bar is charged by induction using a positively charged rod. The bar ends up:", "el": "Μια ουδέτερη μεταλλική ράβδος φορτίζεται με επαγωγή από θετικά φορτισμένη ράβδο. Η ράβδος καταλήγει:"}, "o": [{"en": "positive", "el": "θετική"}, {"en": "negative", "el": "αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 1, "tags": ["contact_induction", null, "ground_order"], "x": {"en": "Induction (with grounding) leaves the opposite sign: electrons come in from ground and stay.", "el": "Η επαγωγή (με γείωση) αφήνει το αντίθετο πρόσημο: ηλεκτρόνια έρχονται από τη γη και μένουν."}, "status": "new"}, {"id": "L02-contact", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "A neutral metal bar touched by a positively charged rod becomes:", "el": "Μια ουδέτερη μεταλλική ράβδος που ακουμπά θετικά φορτισμένη ράβδο γίνεται:"}, "o": [{"en": "positive", "el": "θετική"}, {"en": "negative", "el": "αρνητική"}, {"en": "neutral", "el": "ουδέτερη"}], "a": 0, "tags": [null, "contact_induction", "conservation"], "x": {"en": "By contact the bar takes the same sign as the rod: the rod pulls electrons out of it.", "el": "Με επαφή η ράβδος παίρνει το ίδιο πρόσημο: η φορτισμένη ράβδος της αφαιρεί ηλεκτρόνια."}, "status": "new"}, {"id": "L02-coulombunit", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "One coulomb is the charge carried by:", "el": "Ένα coulomb είναι το φορτίο που μεταφέρει:"}, "o": [{"en": "one ampere in one second", "el": "ρεύμα ενός ampere σε ένα δευτερόλεπτο"}, {"en": "one electron", "el": "ένα ηλεκτρόνιο"}, {"en": "one volt across one ohm", "el": "τάση ενός volt σε ένα ohm"}], "a": 0, "tags": [null, "elementary_charge", "ohm_mixup"], "x": {"en": "Q = I × t, so 1 C = 1 A × 1 s.", "el": "Q = I × t, άρα 1 C = 1 A × 1 s."}, "status": "new"}, {"id": "L02-electrons", "lesson": "L02", "topic": "3.02", "d": 2, "units": "SI", "q": {"en": "A current of 2 A flows for 1 s. About how many electrons pass a point?", "el": "Ρεύμα 2 A ρέει για 1 s. Περίπου πόσα ηλεκτρόνια περνούν από ένα σημείο;"}, "o": [{"en": "6.24 × 10¹⁸", "el": "6,24 × 10¹⁸"}, {"en": "1.25 × 10¹⁹", "el": "1,25 × 10¹⁹"}, {"en": "3.2 × 10⁻¹⁹", "el": "3,2 × 10⁻¹⁹"}], "a": 1, "tags": ["forgot_current", null, "inverted_e"], "x": {"en": "Q = 2 A × 1 s = 2 C, and 2 × 6.24 × 10¹⁸ ≈ 1.25 × 10¹⁹ electrons.", "el": "Q = 2 A × 1 s = 2 C, και 2 × 6,24 × 10¹⁸ ≈ 1,25 × 10¹⁹ ηλεκτρόνια."}, "status": "new"}, {"id": "L02-dist2", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "The distance between two point charges is doubled. The force between them:", "el": "Η απόσταση δύο σημειακών φορτίων διπλασιάζεται. Η δύναμη μεταξύ τους:"}, "o": [{"en": "halves", "el": "υποδιπλασιάζεται"}, {"en": "falls to a quarter", "el": "γίνεται το ένα τέταρτο"}, {"en": "doubles", "el": "διπλασιάζεται"}], "a": 1, "tags": ["forgot_square_d", null, "inverse_mixup"], "x": {"en": "F ∝ 1/d²: doubling d divides F by 2² = 4.", "el": "F ∝ 1/d²: διπλάσια απόσταση διαιρεί τη δύναμη με 2² = 4."}, "status": "new"}, {"id": "L02-both2", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "Both charges are doubled and the distance stays the same. The force:", "el": "Διπλασιάζονται και τα δύο φορτία, ενώ η απόσταση μένει ίδια. Η δύναμη:"}, "o": [{"en": "doubles", "el": "διπλασιάζεται"}, {"en": "becomes four times larger", "el": "τετραπλασιάζεται"}, {"en": "stays the same", "el": "μένει ίδια"}], "a": 1, "tags": ["one_charge", null, "inverse_mixup"], "x": {"en": "F ∝ Q₁ × Q₂: 2 × 2 = 4 times larger.", "el": "F ∝ Q₁ × Q₂: 2 × 2 = 4 φορές μεγαλύτερη."}, "status": "new"}, {"id": "L02-dist3", "lesson": "L02", "topic": "3.02", "d": 3, "units": "—", "q": {"en": "Two charges repel with 36 N. The distance between them is tripled. The new force is:", "el": "Δύο φορτία απωθούνται με 36 N. Η απόσταση τριπλασιάζεται. Η νέα δύναμη είναι:"}, "o": [{"en": "12 N", "el": "12 N"}, {"en": "4 N", "el": "4 N"}, {"en": "108 N", "el": "108 N"}], "a": 1, "tags": ["forgot_square_d", null, "inverse_mixup"], "x": {"en": "F ∝ 1/d²: 36 N ÷ 3² = 36 ÷ 9 = 4 N.", "el": "F ∝ 1/d²: 36 N ÷ 3² = 36 ÷ 9 = 4 N."}, "status": "new"}, {"id": "L02-coulombcalc", "lesson": "L02", "topic": "3.02", "d": 3, "units": "SI", "q": {"en": "Two charges of 1 µC each are 0.1 m apart (k = 9 × 10⁹ N·m²/C²). The force between them is:", "el": "Δύο φορτία 1 µC το καθένα απέχουν 0,1 m (k = 9 × 10⁹ N·m²/C²). Η δύναμη μεταξύ τους είναι:"}, "o": [{"en": "0.09 N", "el": "0,09 N"}, {"en": "0.9 N", "el": "0,9 N"}, {"en": "9 N", "el": "9 N"}], "a": 1, "tags": ["forgot_square_d", null, "prefix_error"], "x": {"en": "F = 9 × 10⁹ × (10⁻⁶ × 10⁻⁶) / 0.1² = 9 × 10⁻³ / 10⁻² = 0.9 N.", "el": "F = 9 × 10⁹ × (10⁻⁶ × 10⁻⁶) / 0,1² = 9 × 10⁻³ / 10⁻² = 0,9 N."}, "status": "new"}, {"id": "L02-esd", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Before handling an ESD-sensitive circuit card, a technician should:", "el": "Πριν πιάσει μια κάρτα ευαίσθητη σε ESD, ο τεχνικός πρέπει:"}, "o": [{"en": "wear a grounding wrist strap", "el": "να φορέσει γειωμένο βραχιόλι (wrist strap)"}, {"en": "touch the connector pins to discharge them", "el": "να ακουμπήσει τις ακίδες του connector για να τις εκφορτίσει"}, {"en": "place it on a carpet-covered toolbox", "el": "να την ακουμπήσει σε εργαλειοθήκη με μοκέτα"}], "a": 0, "tags": [null, "esd_pins", "esd_carpet"], "x": {"en": "The strap keeps your body at ground potential, so no discharge goes through the card.", "el": "Το βραχιόλι κρατά το σώμα στο δυναμικό της γης, οπότε δεν περνά εκφόρτιση από την κάρτα."}, "status": "new"}, {"id": "L02-ohmmeter", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "When testing transistors, ohmmeter ranges should not be used if they drive more than:", "el": "Στον έλεγχο τρανζίστορ δεν χρησιμοποιούνται κλίμακες ωμομέτρου που δίνουν ρεύμα πάνω από:"}, "o": [{"en": "1 mA", "el": "1 mA"}, {"en": "1 A", "el": "1 A"}, {"en": "1 µA", "el": "1 µA"}], "a": 0, "tags": [null, "prefix_error", "prefix_error"], "x": {"en": "The precaution in the course: no ohmmeter range above 1 mA on a transistor.", "el": "Η προφύλαξη του μαθήματος: όχι κλίμακα ωμομέτρου πάνω από 1 mA σε τρανζίστορ."}, "status": "new"}, {"id": "L02-refuel", "lesson": "L02", "topic": "3.02", "d": 1, "units": "—", "q": {"en": "Before refuelling, the aircraft and the fuel truck are bonded and grounded because:", "el": "Πριν τον ανεφοδιασμό, το αεροσκάφος και το βυτιοφόρο συνδέονται (bonding) και γειώνονται επειδή:"}, "o": [{"en": "flowing fuel builds up static charge that could spark", "el": "η ροή καυσίμου δημιουργεί στατικό φορτίο που μπορεί να δώσει σπινθήρα"}, {"en": "fuel is a good conductor", "el": "το καύσιμο είναι καλός αγωγός"}, {"en": "the pumps need a return path for their current", "el": "οι αντλίες χρειάζονται δρόμο επιστροφής ρεύματος"}], "a": 0, "tags": [null, "fuel_conductor", "static_dynamic"], "x": {"en": "Fuel is a poor conductor, so flow through hoses and filters builds up charge. Bonding keeps everything at the same potential.", "el": "Το καύσιμο είναι κακός αγωγός, οπότε η ροή σε σωλήνες και φίλτρα φορτίζει. Το bonding κρατά τα πάντα στο ίδιο δυναμικό."}, "status": "new"}, {"id": "L02-liquids", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "In a conducting liquid such as salt water, the current is carried by:", "el": "Σε αγώγιμο υγρό, όπως το αλατόνερο, το ρεύμα μεταφέρεται από:"}, "o": [{"en": "free electrons only", "el": "μόνο ελεύθερα ηλεκτρόνια"}, {"en": "positive and negative ions", "el": "θετικά και αρνητικά ιόντα"}, {"en": "protons only", "el": "μόνο πρωτόνια"}], "a": 1, "tags": ["metal_liquid", null, "nucleus_carrier"], "x": {"en": "In electrolytes both kinds of ions move. Only in metals are free electrons the carriers.", "el": "Στους ηλεκτρολύτες κινούνται και τα δύο είδη ιόντων. Μόνο στα μέταλλα φορείς είναι τα ελεύθερα ηλεκτρόνια."}, "status": "new"}, {"id": "L02-gas", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A gas normally behaves as:", "el": "Ένα αέριο κανονικά συμπεριφέρεται ως:"}, "o": [{"en": "a good conductor", "el": "καλός αγωγός"}, {"en": "an insulator, until a strong field ionizes it", "el": "μονωτής, μέχρι να το ιονίσει ισχυρό πεδίο"}, {"en": "a semiconductor", "el": "ημιαγωγός"}], "a": 1, "tags": ["gas_conductor", null, "gas_conductor"], "x": {"en": "Gases have almost no free carriers. A strong field ionizes them: sparks, lightning, neon lamps.", "el": "Τα αέρια δεν έχουν σχεδόν ελεύθερους φορείς. Ισχυρό πεδίο τα ιονίζει: σπινθήρες, κεραυνοί, λάμπες νέον."}, "status": "new"}, {"id": "L02-vacuum", "lesson": "L02", "topic": "3.02", "d": 2, "units": "—", "q": {"en": "A vacuum can carry a current only if:", "el": "Το κενό μπορεί να άγει ρεύμα μόνο αν:"}, "o": [{"en": "electrons are injected into it, e.g. from a heated cathode", "el": "εισαχθούν ηλεκτρόνια, π.χ. από θερμαινόμενη κάθοδο"}, {"en": "it is ionized", "el": "ιονιστεί"}, {"en": "it is cooled", "el": "ψυχθεί"}], "a": 0, "tags": [null, "vacuum_ions", "vacuum_ions"], "x": {"en": "A vacuum has no carriers of its own. Electrons put into it move freely (vacuum tubes, CRTs).", "el": "Το κενό δεν έχει δικούς του φορείς. Ηλεκτρόνια που εισάγονται κινούνται ελεύθερα (λυχνίες κενού, CRT)."}, "status": "new"}, {"id": "L03-mA", "lesson": "L03", "topic": "3.03", "d": 1, "units": "SI", "q": {"en": "0.25 A is the same as:", "el": "Τα 0,25 A ισούνται με:"}, "o": [{"en": "25 mA", "el": "25 mA"}, {"en": "250 mA", "el": "250 mA"}, {"en": "2 500 mA", "el": "2 500 mA"}], "a": 1, "tags": ["prefix_step", null, "prefix_step"], "x": {"en": "A → mA: multiply by 1 000. 0.25 × 1 000 = 250 mA.", "el": "A → mA: επί 1 000. 0,25 × 1 000 = 250 mA."}, "status": "new"}, {"id": "L03-kV", "lesson": "L03", "topic": "3.03", "d": 1, "units": "SI", "q": {"en": "3 500 V is the same as:", "el": "Τα 3 500 V ισούνται με:"}, "o": [{"en": "3.5 kV", "el": "3,5 kV"}, {"en": "35 kV", "el": "35 kV"}, {"en": "0.35 kV", "el": "0,35 kV"}], "a": 0, "tags": [null, "prefix_step", "prefix_step"], "x": {"en": "V → kV: divide by 1 000. 3 500 / 1 000 = 3.5 kV.", "el": "V → kV: διά 1 000. 3 500 / 1 000 = 3,5 kV."}, "status": "new"}, {"id": "L03-uA", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "0.000 05 A is the same as:", "el": "Τα 0,000 05 A ισούνται με:"}, "o": [{"en": "5 µA", "el": "5 µA"}, {"en": "50 µA", "el": "50 µA"}, {"en": "0.05 µA", "el": "0,05 µA"}], "a": 1, "tags": ["prefix_step", null, "prefix_direction"], "x": {"en": "A → µA: multiply by 10⁶. 0.000 05 × 1 000 000 = 50 µA.", "el": "A → µA: επί 10⁶. 0,000 05 × 1 000 000 = 50 µA."}, "status": "new"}, {"id": "L03-Mk", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "2.2 MΩ is the same as:", "el": "Τα 2,2 MΩ ισούνται με:"}, "o": [{"en": "2 200 kΩ", "el": "2 200 kΩ"}, {"en": "220 kΩ", "el": "220 kΩ"}, {"en": "0.0022 kΩ", "el": "0,0022 kΩ"}], "a": 0, "tags": [null, "prefix_step", "mega_milli"], "x": {"en": "One step down (M → k): multiply by 1 000. 2.2 × 1 000 = 2 200 kΩ.", "el": "Ένα βήμα κάτω (M → k): επί 1 000. 2,2 × 1 000 = 2 200 kΩ."}, "status": "new"}, {"id": "L03-micro", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "The prefix micro (µ) means:", "el": "Το πρόθεμα micro (µ) σημαίνει:"}, "o": [{"en": "one thousandth (10⁻³)", "el": "ένα χιλιοστό (10⁻³)"}, {"en": "one millionth (10⁻⁶)", "el": "ένα εκατομμυριοστό (10⁻⁶)"}, {"en": "one million (10⁶)", "el": "ένα εκατομμύριο (10⁶)"}], "a": 1, "tags": ["milli_micro", null, "mega_milli"], "x": {"en": "micro = 10⁻⁶. milli = 10⁻³, mega = 10⁶.", "el": "micro = 10⁻⁶. milli = 10⁻³, mega = 10⁶."}, "status": "new"}, {"id": "L03-Mm", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "The symbol M (capital) stands for:", "el": "Το σύμβολο M (κεφαλαίο) σημαίνει:"}, "o": [{"en": "milli, 10⁻³", "el": "milli, 10⁻³"}, {"en": "mega, 10⁶", "el": "mega, 10⁶"}, {"en": "micro, 10⁻⁶", "el": "micro, 10⁻⁶"}], "a": 1, "tags": ["mega_milli", null, "milli_micro"], "x": {"en": "Capital M = mega (10⁶); small m = milli (10⁻³).", "el": "Κεφαλαίο M = mega (10⁶)· μικρό m = milli (10⁻³)."}, "status": "new"}, {"id": "L03-Idef", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "Electric current is:", "el": "Το ηλεκτρικό ρεύμα είναι:"}, "o": [{"en": "the rate of flow of charge", "el": "ο ρυθμός ροής φορτίου"}, {"en": "the total charge stored", "el": "το συνολικό αποθηκευμένο φορτίο"}, {"en": "the energy per unit charge", "el": "η ενέργεια ανά μονάδα φορτίου"}], "a": 0, "tags": [null, "charge_current", "voltage_current"], "x": {"en": "I = Q / t: charge per second.", "el": "I = Q / t: φορτίο ανά δευτερόλεπτο."}, "status": "new"}, {"id": "L03-Icalc", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "A charge of 30 C passes a point in 6 s. The current is:", "el": "Φορτίο 30 C περνά από ένα σημείο σε 6 s. Το ρεύμα είναι:"}, "o": [{"en": "180 A", "el": "180 A"}, {"en": "5 A", "el": "5 A"}, {"en": "0.2 A", "el": "0,2 A"}], "a": 1, "tags": ["multiplied", null, "inverted"], "x": {"en": "I = Q / t = 30 / 6 = 5 A.", "el": "I = Q / t = 30 / 6 = 5 A."}, "status": "new"}, {"id": "L03-Qcalc", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "A current of 2 A flows for 1 minute. The charge that passes is:", "el": "Ρεύμα 2 A ρέει για 1 λεπτό. Το φορτίο που περνά είναι:"}, "o": [{"en": "2 C", "el": "2 C"}, {"en": "120 C", "el": "120 C"}, {"en": "30 C", "el": "30 C"}], "a": 1, "tags": ["minutes", null, "inverted"], "x": {"en": "Q = I × t = 2 A × 60 s = 120 C. Time must be in seconds.", "el": "Q = I × t = 2 A × 60 s = 120 C. Ο χρόνος σε δευτερόλεπτα."}, "status": "new"}, {"id": "L03-Vdef", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "One volt is:", "el": "Ένα volt είναι:"}, "o": [{"en": "one joule per coulomb", "el": "ένα joule ανά coulomb"}, {"en": "one coulomb per second", "el": "ένα coulomb ανά δευτερόλεπτο"}, {"en": "one ampere per ohm", "el": "ένα ampere ανά ohm"}], "a": 0, "tags": [null, "voltage_current", "ohm_inverse"], "x": {"en": "V = W / Q: energy per unit charge.", "el": "V = W / Q: ενέργεια ανά μονάδα φορτίου."}, "status": "new"}, {"id": "L03-Vcalc", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "Moving 4 C of charge between two points takes 48 J. The potential difference is:", "el": "Για τη μετακίνηση 4 C μεταξύ δύο σημείων απαιτούνται 48 J. Η διαφορά δυναμικού είναι:"}, "o": [{"en": "12 V", "el": "12 V"}, {"en": "192 V", "el": "192 V"}, {"en": "0.083 V", "el": "0,083 V"}], "a": 0, "tags": [null, "multiplied", "inverted"], "x": {"en": "V = W / Q = 48 / 4 = 12 V.", "el": "V = W / Q = 48 / 4 = 12 V."}, "status": "new"}, {"id": "L03-Vwatt", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "Between two points of a conductor carrying 1 A, 1 W is dissipated. The potential difference is:", "el": "Μεταξύ δύο σημείων αγωγού που διαρρέεται από 1 A καταναλώνεται 1 W. Η διαφορά δυναμικού είναι:"}, "o": [{"en": "1 V", "el": "1 V"}, {"en": "1 Ω", "el": "1 Ω"}, {"en": "1 J", "el": "1 J"}], "a": 0, "tags": [null, "unit_mixup", "unit_mixup"], "x": {"en": "That is the definition of the volt: V = P / I = 1 W / 1 A = 1 V.", "el": "Αυτός είναι ο ορισμός του volt: V = P / I = 1 W / 1 A = 1 V."}, "status": "new"}, {"id": "L03-tanks", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "In the water-tank picture, what makes the water flow from tank A (10 psi) to tank B (2 psi)?", "el": "Στο παράδειγμα με τις δεξαμενές, τι κάνει το νερό να ρέει από τη δεξαμενή A (10 psi) στη B (2 psi);"}, "o": [{"en": "the 10 psi in tank A", "el": "τα 10 psi της δεξαμενής A"}, {"en": "the 8 psi difference between the tanks", "el": "η διαφορά 8 psi μεταξύ των δεξαμενών"}, {"en": "the 12 psi total", "el": "τα συνολικά 12 psi"}], "a": 1, "tags": ["absolute_potential", null, "absolute_potential"], "x": {"en": "Flow is driven by the difference: 10 − 2 = 8 psi. Likewise current is driven by a potential difference.", "el": "Τη ροή την προκαλεί η διαφορά: 10 − 2 = 8 psi. Αντίστοιχα το ρεύμα το προκαλεί διαφορά δυναμικού."}, "status": "new"}, {"id": "L03-emf", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "Electromotive force (emf) is best described as:", "el": "Η ηλεκτρεγερτική δύναμη (ΗΕΔ) περιγράφεται καλύτερα ως:"}, "o": [{"en": "the push given to charges by a source such as a battery or generator", "el": "η «ώθηση» που δίνει στα φορτία μια πηγή, π.χ. μπαταρία ή γεννήτρια"}, {"en": "the opposition to current in a load", "el": "η αντίσταση στο ρεύμα ενός φορτίου"}, {"en": "the force between two charges", "el": "η δύναμη μεταξύ δύο φορτίων"}], "a": 0, "tags": [null, "resistance_emf", "coulomb_emf"], "x": {"en": "An emf is produced inside a source and drives current round the circuit; it is measured in volts.", "el": "Η ΗΕΔ δημιουργείται μέσα στην πηγή και κινεί το ρεύμα στο κύκλωμα· μετριέται σε volt."}, "status": "new"}, {"id": "L03-wire", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "The potential difference along a connecting wire in a working circuit is normally:", "el": "Η διαφορά δυναμικού κατά μήκος ενός καλωδίου σύνδεσης σε κύκλωμα που λειτουργεί είναι συνήθως:"}, "o": [{"en": "almost zero", "el": "σχεδόν μηδέν"}, {"en": "equal to the battery voltage", "el": "ίση με την τάση της μπαταρίας"}, {"en": "larger than across the load", "el": "μεγαλύτερη από αυτή στο φορτίο"}], "a": 0, "tags": [null, "wire_drop", "wire_drop"], "x": {"en": "Wires have very little resistance, so almost no voltage is dropped along them; it appears across the load.", "el": "Τα καλώδια έχουν πολύ μικρή αντίσταση, οπότε η τάση πέφτει σχεδόν όλη στο φορτίο."}, "status": "new"}, {"id": "L03-drift", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "Electrons in a wire carrying current move with a drift velocity that is:", "el": "Τα ηλεκτρόνια σε αγωγό που διαρρέεται από ρεύμα κινούνται με ταχύτητα ολίσθησης:"}, "o": [{"en": "close to the speed of light", "el": "κοντά στην ταχύτητα του φωτός"}, {"en": "very slow, a fraction of a millimetre per second", "el": "πολύ μικρή, κλάσμα του χιλιοστού ανά δευτερόλεπτο"}, {"en": "about the speed of sound", "el": "περίπου ίση με την ταχύτητα του ήχου"}], "a": 1, "tags": ["signal_speed", null, "signal_speed"], "x": {"en": "The electrons drift slowly; the effect travels fast because the wire is already full of free electrons (balls in a tube).", "el": "Τα ηλεκτρόνια ολισθαίνουν αργά· το αποτέλεσμα διαδίδεται γρήγορα γιατί ο αγωγός είναι ήδη γεμάτος ελεύθερα ηλεκτρόνια."}, "status": "new"}, {"id": "L03-Runit", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "The unit of resistance is the:", "el": "Η μονάδα της αντίστασης είναι το:"}, "o": [{"en": "siemens", "el": "siemens"}, {"en": "ohm", "el": "ohm"}, {"en": "volt", "el": "volt"}], "a": 1, "tags": ["ohm_inverse", null, "unit_mixup"], "x": {"en": "Resistance in ohms (Ω); its inverse, conductance, in siemens (S).", "el": "Αντίσταση σε ohm (Ω)· το αντίστροφό της, η αγωγιμότητα, σε siemens (S)."}, "status": "new"}, {"id": "L03-Gcalc", "lesson": "L03", "topic": "3.03", "d": 2, "units": "SI", "q": {"en": "A resistor of 50 Ω has a conductance of:", "el": "Αντιστάτης 50 Ω έχει αγωγιμότητα:"}, "o": [{"en": "50 S", "el": "50 S"}, {"en": "0.02 S", "el": "0,02 S"}, {"en": "2 S", "el": "2 S"}], "a": 1, "tags": ["ohm_inverse", null, "inverse_calc"], "x": {"en": "G = 1 / R = 1 / 50 = 0.02 S.", "el": "G = 1 / R = 1 / 50 = 0,02 S."}, "status": "new"}, {"id": "L03-Gdouble", "lesson": "L03", "topic": "3.03", "d": 2, "units": "—", "q": {"en": "The voltage is kept constant and the conductance of a component is doubled. The current:", "el": "Η τάση μένει σταθερή και η αγωγιμότητα ενός στοιχείου διπλασιάζεται. Το ρεύμα:"}, "o": [{"en": "doubles", "el": "διπλασιάζεται"}, {"en": "halves", "el": "υποδιπλασιάζεται"}, {"en": "stays the same", "el": "μένει ίδιο"}], "a": 0, "tags": [null, "G_R_mixup", "G_R_mixup"], "x": {"en": "I = G × V: current is proportional to conductance.", "el": "I = G × V: το ρεύμα είναι ανάλογο της αγωγιμότητας."}, "status": "new"}, {"id": "L03-conv", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "Conventional current flows in the external circuit:", "el": "Η συμβατική φορά του ρεύματος στο εξωτερικό κύκλωμα είναι:"}, "o": [{"en": "from + to −", "el": "από το + στο −"}, {"en": "from − to +", "el": "από το − στο +"}, {"en": "in both directions", "el": "και προς τις δύο κατευθύνσεις"}], "a": 0, "tags": [null, "flow_direction", "flow_direction"], "x": {"en": "Conventional (Franklin): + to −. Electrons actually go − to +.", "el": "Συμβατική (Franklin): από + σε −. Τα ηλεκτρόνια κινούνται από − σε +."}, "status": "new"}, {"id": "L03-eflow", "lesson": "L03", "topic": "3.03", "d": 1, "units": "—", "q": {"en": "Electron flow in the external circuit is:", "el": "Η ροή ηλεκτρονίων στο εξωτερικό κύκλωμα είναι:"}, "o": [{"en": "from + to −", "el": "από το + στο −"}, {"en": "from − to +", "el": "από το − στο +"}, {"en": "from the load to ground only", "el": "μόνο από το φορτίο προς τη γη"}], "a": 1, "tags": ["flow_direction", null, "flow_direction"], "x": {"en": "Electrons leave the negative terminal and are attracted to the positive one.", "el": "Τα ηλεκτρόνια φεύγουν από τον αρνητικό πόλο και έλκονται από τον θετικό."}, "status": "new"}, {"id": "L04-seven", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "Which of these is NOT one of the methods of producing electricity in the syllabus?", "el": "Ποιο από τα παρακάτω ΔΕΝ είναι μέθοδος παραγωγής ηλεκτρισμού της ύλης;"}, "o": [{"en": "pressure", "el": "πίεση"}, {"en": "magnetism and motion", "el": "μαγνητισμός και κίνηση"}, {"en": "sound absorption", "el": "απορρόφηση ήχου"}], "a": 2, "tags": ["seven_list", "seven_list", null], "x": {"en": "The seven: light, heat, friction, pressure, chemical action, magnetism and motion.", "el": "Οι επτά: φως, θερμότητα, τριβή, πίεση, χημική δράση, μαγνητισμός και κίνηση."}, "status": "new"}, {"id": "L04-solar", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "A photovoltaic (solar) cell converts:", "el": "Ένα φωτοβολταϊκό στοιχείο μετατρέπει:"}, "o": [{"en": "light into electricity", "el": "φως σε ηλεκτρισμό"}, {"en": "heat into electricity", "el": "θερμότητα σε ηλεκτρισμό"}, {"en": "electricity into light", "el": "ηλεκτρισμό σε φως"}], "a": 0, "tags": [null, "source_mixup", "reverse_device"], "x": {"en": "Photons free electrons in a semiconductor such as silicon.", "el": "Τα φωτόνια ελευθερώνουν ηλεκτρόνια σε ημιαγωγό, π.χ. πυρίτιο."}, "status": "new"}, {"id": "L04-holes", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "In a solar cell, the 'holes' are:", "el": "Σε ένα φωτοβολταϊκό, οι «οπές» είναι:"}, "o": [{"en": "missing electrons that act as positive charges", "el": "ελλείψεις ηλεκτρονίων που συμπεριφέρονται ως θετικά φορτία"}, {"en": "small gaps in the silicon surface", "el": "μικρά κενά στην επιφάνεια του πυριτίου"}, {"en": "free protons", "el": "ελεύθερα πρωτόνια"}], "a": 0, "tags": [null, "hole_literal", "nucleus_carrier"], "x": {"en": "A hole is the absence of an electron; it moves opposite to the electrons, like a positive charge.", "el": "Οπή είναι η απουσία ηλεκτρονίου· κινείται αντίθετα στα ηλεκτρόνια, σαν θετικό φορτίο."}, "status": "new"}, {"id": "L04-tc", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "A thermocouple is made of:", "el": "Ένα θερμοζεύγος αποτελείται από:"}, "o": [{"en": "two dissimilar metals joined at a junction", "el": "δύο ανόμοια μέταλλα ενωμένα σε μια επαφή"}, {"en": "two identical metal wires", "el": "δύο ίδια μεταλλικά σύρματα"}, {"en": "a semiconductor and a crystal", "el": "έναν ημιαγωγό και έναν κρύσταλλο"}], "a": 0, "tags": [null, "same_metals", "source_mixup"], "x": {"en": "Only a pair of different metals gives a Seebeck voltage.", "el": "Μόνο ζεύγος διαφορετικών μετάλλων δίνει τάση Seebeck."}, "status": "new"}, {"id": "L04-seebeck", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "The generation of a voltage by a thermocouple is called the:", "el": "Η παραγωγή τάσης από θερμοζεύγος λέγεται φαινόμενο:"}, "o": [{"en": "Seebeck effect", "el": "Seebeck"}, {"en": "piezoelectric effect", "el": "πιεζοηλεκτρικό"}, {"en": "triboelectric effect", "el": "τριβοηλεκτρικό"}], "a": 0, "tags": [null, "source_mixup", "source_mixup"], "x": {"en": "Seebeck, 1821: heat → voltage in a circuit of two dissimilar metals.", "el": "Seebeck, 1821: θερμότητα → τάση σε κύκλωμα δύο ανόμοιων μετάλλων."}, "status": "new"}, {"id": "L04-tcdiff", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "The emf of a thermocouple depends on:", "el": "Η ΗΕΔ ενός θερμοζεύγους εξαρτάται από:"}, "o": [{"en": "the temperature difference between the hot and cold junctions", "el": "τη διαφορά θερμοκρασίας μεταξύ θερμής και ψυχρής επαφής"}, {"en": "the temperature of the hot junction only", "el": "μόνο τη θερμοκρασία της θερμής επαφής"}, {"en": "the length of the wires", "el": "το μήκος των συρμάτων"}], "a": 0, "tags": [null, "tc_absolute", "tc_length"], "x": {"en": "Both junctions at the same temperature give no emf, whatever the temperature.", "el": "Αν οι δύο επαφές έχουν ίδια θερμοκρασία, ΗΕΔ δεν υπάρχει, όποια κι αν είναι η θερμοκρασία."}, "status": "new"}, {"id": "L04-tcuniform", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "Both junctions of a thermocouple are heated to 500 °C. The output emf is:", "el": "Και οι δύο επαφές ενός θερμοζεύγους θερμαίνονται στους 500 °C. Η ΗΕΔ εξόδου είναι:"}, "o": [{"en": "maximum", "el": "μέγιστη"}, {"en": "zero", "el": "μηδέν"}, {"en": "negative", "el": "αρνητική"}], "a": 1, "tags": ["tc_absolute", null, "tc_absolute"], "x": {"en": "No temperature difference, no emf.", "el": "Χωρίς διαφορά θερμοκρασίας δεν υπάρχει ΗΕΔ."}, "status": "new"}, {"id": "L04-egt", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "Turbine engine EGT thermocouples are usually made of:", "el": "Τα θερμοζεύγη EGT στροβιλοκινητήρων είναι συνήθως από:"}, "o": [{"en": "chromel and alumel", "el": "chromel και alumel"}, {"en": "iron and constantan", "el": "σίδηρο και constantan"}, {"en": "copper and silver", "el": "χαλκό και άργυρο"}], "a": 0, "tags": [null, "cht_egt", "same_metals"], "x": {"en": "Chromel–alumel (type K) for EGT; iron or copper with constantan for piston CHT.", "el": "Chromel–alumel (τύπος K) για EGT· σίδηρος ή χαλκός με constantan για CHT εμβολοφόρων."}, "status": "new"}, {"id": "L04-tcuse", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "On aircraft, thermocouples are mainly used for:", "el": "Στα αεροσκάφη τα θερμοζεύγη χρησιμοποιούνται κυρίως για:"}, "o": [{"en": "measuring engine temperatures and detecting fire", "el": "μέτρηση θερμοκρασιών κινητήρα και ανίχνευση φωτιάς"}, {"en": "supplying the main DC bus", "el": "τροφοδοσία του κύριου DC bus"}, {"en": "starting the engines", "el": "εκκίνηση των κινητήρων"}], "a": 0, "tags": [null, "tc_power", "tc_power"], "x": {"en": "Their output is only millivolts: good for sensing (EGT, CHT, ITT, fire detection), not for power.", "el": "Η έξοδός τους είναι μόνο millivolt: κατάλληλη για μέτρηση (EGT, CHT, ITT, ανίχνευση φωτιάς), όχι για ισχύ."}, "status": "new"}, {"id": "L04-friction", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "Electricity produced by friction is:", "el": "Ο ηλεκτρισμός που παράγεται με τριβή είναι:"}, "o": [{"en": "static electricity", "el": "στατικός ηλεκτρισμός"}, {"en": "alternating current", "el": "εναλλασσόμενο ρεύμα"}, {"en": "a steady direct current", "el": "σταθερό συνεχές ρεύμα"}], "a": 0, "tags": [null, "static_dynamic", "static_dynamic"], "x": {"en": "Rubbing insulators transfers electrons: a static charge, not a steady current.", "el": "Η τριβή μονωτών μεταφέρει ηλεκτρόνια: στατικό φορτίο, όχι σταθερό ρεύμα."}, "status": "new"}, {"id": "L04-piezo", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "The piezoelectric effect produces a voltage when a crystal is:", "el": "Το πιεζοηλεκτρικό φαινόμενο δίνει τάση όταν ένας κρύσταλλος:"}, "o": [{"en": "heated", "el": "θερμαίνεται"}, {"en": "mechanically stressed (squeezed)", "el": "καταπονείται μηχανικά (συμπιέζεται)"}, {"en": "lit", "el": "φωτίζεται"}], "a": 1, "tags": ["source_mixup", null, "source_mixup"], "x": {"en": "Piezo = press. Stress polarizes the crystal and a voltage appears across it.", "el": "Πιέζω: η μηχανική τάση πολώνει τον κρύσταλλο και εμφανίζεται τάση στα άκρα του."}, "status": "new"}, {"id": "L04-piezomat", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "A common piezoelectric material is:", "el": "Ένα κοινό πιεζοηλεκτρικό υλικό είναι:"}, "o": [{"en": "quartz", "el": "ο χαλαζίας (quartz)"}, {"en": "copper", "el": "ο χαλκός"}, {"en": "constantan", "el": "το constantan"}], "a": 0, "tags": [null, "conductor_piezo", "cht_egt"], "x": {"en": "Quartz, Rochelle salt and barium titanate. Piezoelectric materials are insulating crystals, not metals.", "el": "Χαλαζίας, άλας Rochelle και τιτανικό βάριο. Τα πιεζοηλεκτρικά είναι μονωτικοί κρύσταλλοι, όχι μέταλλα."}, "status": "new"}, {"id": "L04-piezorev", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "Applying a voltage across a piezoelectric crystal:", "el": "Αν εφαρμοστεί τάση σε πιεζοηλεκτρικό κρύσταλλο:"}, "o": [{"en": "makes it change shape slightly", "el": "αλλάζει ελαφρά σχήμα"}, {"en": "heats it until it glows", "el": "θερμαίνεται μέχρι να φωτοβολήσει"}, {"en": "has no effect", "el": "δεν συμβαίνει τίποτα"}], "a": 0, "tags": [null, "source_mixup", "piezo_oneway"], "x": {"en": "The effect works both ways: voltage → distortion (headphones, buzzers, quartz oscillators).", "el": "Το φαινόμενο λειτουργεί και αντίστροφα: τάση → παραμόρφωση (ακουστικά, buzzer, ταλαντωτές χαλαζία)."}, "status": "new"}, {"id": "L04-piezouse", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "Which device uses the piezoelectric effect to turn vibration into an electrical signal?", "el": "Ποια διάταξη χρησιμοποιεί το πιεζοηλεκτρικό φαινόμενο για να μετατρέψει δόνηση σε ηλεκτρικό σήμα;"}, "o": [{"en": "an engine vibration sensor", "el": "αισθητήρας δονήσεων κινητήρα"}, {"en": "an EGT probe", "el": "αισθητήρας EGT"}, {"en": "a lead-acid battery", "el": "μπαταρία μολύβδου"}], "a": 0, "tags": [null, "source_mixup", "source_mixup"], "x": {"en": "Vibration sensors, microphones and pickups: stress → voltage.", "el": "Αισθητήρες δονήσεων, μικρόφωνα, pickups: μηχανική τάση → ηλεκτρική τάση."}, "status": "new"}, {"id": "L04-chem", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "A battery produces electricity by:", "el": "Μια μπαταρία παράγει ηλεκτρισμό με:"}, "o": [{"en": "chemical action", "el": "χημική δράση"}, {"en": "magnetism and motion", "el": "μαγνητισμό και κίνηση"}, {"en": "friction", "el": "τριβή"}], "a": 0, "tags": [null, "source_mixup", "source_mixup"], "x": {"en": "Two different electrodes in an electrolyte: a chemical reaction drives electrons through the external circuit.", "el": "Δύο διαφορετικά ηλεκτρόδια σε ηλεκτρολύτη: μια χημική αντίδραση κινεί ηλεκτρόνια στο εξωτερικό κύκλωμα."}, "status": "new"}, {"id": "L04-chemneg", "lesson": "L04", "topic": "3.04", "d": 3, "units": "—", "q": {"en": "In a cell, the electrode that gives up electrons more readily in the reaction becomes:", "el": "Σε ένα στοιχείο, το ηλεκτρόδιο που δίνει πιο εύκολα ηλεκτρόνια στην αντίδραση γίνεται:"}, "o": [{"en": "the negative terminal", "el": "ο αρνητικός πόλος"}, {"en": "the positive terminal", "el": "ο θετικός πόλος"}, {"en": "neutral", "el": "ουδέτερο"}], "a": 0, "tags": [null, "cell_sign", "conservation"], "x": {"en": "The electrons it releases collect on it, so it is negative (zinc in a dry or alkaline cell). The course deck has this the wrong way round.", "el": "Τα ηλεκτρόνια που απελευθερώνει μαζεύονται πάνω του, οπότε είναι αρνητικό (ο ψευδάργυρος στο ξηρό και το αλκαλικό στοιχείο). Το deck το γράφει ανάποδα."}, "status": "new"}, {"id": "L04-induction", "lesson": "L04", "topic": "3.04", "d": 1, "units": "—", "q": {"en": "When a conductor moves through magnetic lines of flux:", "el": "Όταν ένας αγωγός κινείται μέσα σε μαγνητικές δυναμικές γραμμές:"}, "o": [{"en": "an emf is induced in it", "el": "επάγεται σε αυτόν ΗΕΔ"}, {"en": "it becomes permanently magnetized", "el": "μαγνητίζεται μόνιμα"}, {"en": "its resistance falls to zero", "el": "η αντίστασή του μηδενίζεται"}], "a": 0, "tags": [null, "magnet_mixup", "magnet_mixup"], "x": {"en": "Moving a conductor through flux induces an emf: the principle of every generator.", "el": "Η κίνηση αγωγού μέσα σε μαγνητική ροή επάγει ΗΕΔ: η αρχή κάθε γεννήτριας."}, "status": "new"}, {"id": "L04-faster", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "Which change increases the emf induced in a conductor moving through a magnetic field?", "el": "Ποια αλλαγή αυξάνει την ΗΕΔ που επάγεται σε αγωγό που κινείται σε μαγνητικό πεδίο;"}, "o": [{"en": "moving it faster", "el": "γρηγορότερη κίνηση"}, {"en": "moving it parallel to the flux lines", "el": "κίνηση παράλληλα στις γραμμές"}, {"en": "stopping it in the field", "el": "ακινητοποίηση μέσα στο πεδίο"}], "a": 0, "tags": [null, "parallel_flux", "stationary"], "x": {"en": "More speed, stronger field or more turns → more emf. No cutting of flux → no emf.", "el": "Μεγαλύτερη ταχύτητα, ισχυρότερο πεδίο ή περισσότερες σπείρες → μεγαλύτερη ΗΕΔ. Χωρίς «κόψιμο» γραμμών, καμία ΗΕΔ."}, "status": "new"}, {"id": "L04-power", "lesson": "L04", "topic": "3.04", "d": 2, "units": "—", "q": {"en": "Which two methods provide the main electrical power on an aircraft?", "el": "Ποιες δύο μέθοδοι δίνουν την κύρια ηλεκτρική ισχύ σε ένα αεροσκάφος;"}, "o": [{"en": "chemical action and magnetism/motion", "el": "χημική δράση και μαγνητισμός/κίνηση"}, {"en": "heat and light", "el": "θερμότητα και φως"}, {"en": "pressure and friction", "el": "πίεση και τριβή"}], "a": 0, "tags": [null, "tc_power", "tc_power"], "x": {"en": "Batteries and engine-driven generators. The others are used for sensing or are hazards.", "el": "Μπαταρίες και γεννήτριες των κινητήρων. Οι άλλες χρησιμοποιούνται σε αισθητήρες ή είναι κίνδυνος."}, "status": "new"}, {"id": "L05-primary", "lesson": "L05", "topic": "3.05", "d": 1, "units": "—", "q": {"en": "A primary cell is one that:", "el": "Πρωτογενές στοιχείο είναι αυτό που:"}, "o": [{"en": "cannot be recharged", "el": "δεν επαναφορτίζεται"}, {"en": "can be recharged many times", "el": "επαναφορτίζεται πολλές φορές"}, {"en": "has no electrolyte", "el": "δεν έχει ηλεκτρολύτη"}], "a": 0, "tags": [null, "primary_secondary", "dry_paste"], "x": {"en": "In a primary cell an electrode is consumed; recharging is not possible and can be dangerous.", "el": "Στο πρωτογενές καταναλώνεται ένα ηλεκτρόδιο· η επαναφόρτιση δεν γίνεται και είναι επικίνδυνη."}, "status": "new"}, {"id": "L05-drycase", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "In a carbon-zinc dry cell, the negative electrode is:", "el": "Σε ξηρό στοιχείο άνθρακα-ψευδαργύρου, το αρνητικό ηλεκτρόδιο είναι:"}, "o": [{"en": "the carbon rod", "el": "η ράβδος άνθρακα"}, {"en": "the zinc case", "el": "το περίβλημα ψευδαργύρου"}, {"en": "the electrolyte paste", "el": "η πάστα του ηλεκτρολύτη"}], "a": 1, "tags": ["dry_poles", null, "dry_paste"], "x": {"en": "Carbon rod = positive (+), zinc case = negative (−).", "el": "Ράβδος άνθρακα = θετικός (+), περίβλημα ψευδαργύρου = αρνητικός (−)."}, "status": "new"}, {"id": "L05-alkaline", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "Compared with carbon-zinc cells, alkaline cells have:", "el": "Σε σύγκριση με τα στοιχεία άνθρακα-ψευδαργύρου, τα αλκαλικά έχουν:"}, "o": [{"en": "higher energy density and longer shelf life at the same voltage", "el": "μεγαλύτερη πυκνότητα ενέργειας και διάρκεια αποθήκευσης, με την ίδια τάση"}, {"en": "a higher voltage per cell", "el": "μεγαλύτερη τάση ανά στοιχείο"}, {"en": "lower energy density", "el": "μικρότερη πυκνότητα ενέργειας"}], "a": 0, "tags": [null, "alk_voltage", "alk_voltage"], "x": {"en": "Both are about 1.5 V; alkaline stores more energy and lasts longer on the shelf.", "el": "Και τα δύο έχουν περίπου 1,5 V· το αλκαλικό αποθηκεύει περισσότερη ενέργεια και διαρκεί περισσότερο."}, "status": "new"}, {"id": "L05-posplate", "lesson": "L05", "topic": "3.05", "d": 1, "units": "—", "q": {"en": "In a charged lead-acid cell, the positive plates are made of:", "el": "Σε φορτισμένο στοιχείο μολύβδου, οι θετικές πλάκες είναι από:"}, "o": [{"en": "lead dioxide (PbO₂)", "el": "διοξείδιο του μολύβδου (PbO₂)"}, {"en": "spongy lead (Pb)", "el": "σπογγώδη μόλυβδο (Pb)"}, {"en": "lead sulphate (PbSO₄)", "el": "θειικό μόλυβδο (PbSO₄)"}], "a": 0, "tags": [null, "plate_swap", "discharged_state"], "x": {"en": "PbO₂ positive, spongy Pb negative. PbSO₄ forms on both during discharge.", "el": "PbO₂ θετική, σπογγώδης Pb αρνητική. Το PbSO₄ σχηματίζεται και στις δύο κατά την εκφόρτιση."}, "status": "new"}, {"id": "L05-electrolyte", "lesson": "L05", "topic": "3.05", "d": 1, "units": "—", "q": {"en": "The electrolyte of a lead-acid battery is:", "el": "Ο ηλεκτρολύτης μιας μπαταρίας μολύβδου είναι:"}, "o": [{"en": "potassium hydroxide and water", "el": "υδροξείδιο του καλίου και νερό"}, {"en": "sulphuric acid and distilled water", "el": "θειικό οξύ και απεσταγμένο νερό"}, {"en": "sodium bicarbonate solution", "el": "διάλυμα διττανθρακικού νατρίου"}], "a": 1, "tags": ["nicad_electrolyte", null, "sump_mixup"], "x": {"en": "H₂SO₄ + distilled water. Potassium hydroxide (KOH) is the nickel-cadmium electrolyte.", "el": "H₂SO₄ + απεσταγμένο νερό. Το KOH είναι ο ηλεκτρολύτης του νικελίου-καδμίου."}, "status": "new"}, {"id": "L05-negplates", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "In a lead-acid cell, compared with the positive plates there is:", "el": "Σε στοιχείο μολύβδου, σε σχέση με τις θετικές πλάκες υπάρχει:"}, "o": [{"en": "one more negative plate", "el": "μία αρνητική πλάκα παραπάνω"}, {"en": "one fewer negative plate", "el": "μία αρνητική πλάκα λιγότερη"}, {"en": "the same number of negative plates", "el": "ίδιος αριθμός αρνητικών πλακών"}], "a": 0, "tags": [null, "plate_count", "plate_count"], "x": {"en": "Each positive plate sits between two negatives, so there is one extra negative.", "el": "Κάθε θετική πλάκα βρίσκεται ανάμεσα σε δύο αρνητικές, οπότε υπάρχει μία αρνητική παραπάνω."}, "status": "new"}, {"id": "L05-separators", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "The separators between lead-acid plates:", "el": "Οι διαχωριστές ανάμεσα στις πλάκες μολύβδου:"}, "o": [{"en": "prevent the plates from touching while letting electrolyte circulate", "el": "εμποδίζουν τις πλάκες να ακουμπήσουν, αφήνοντας τον ηλεκτρολύτη να κυκλοφορεί"}, {"en": "store the acid during discharge", "el": "αποθηκεύουν το οξύ κατά την εκφόρτιση"}, {"en": "connect the cells in series", "el": "συνδέουν τα στοιχεία σε σειρά"}], "a": 0, "tags": [null, "separator_job", "strap_job"], "x": {"en": "Porous and ribbed: no short circuit, free circulation, and sediment can fall to the bottom.", "el": "Πορώδεις με νευρώσεις: κανένα βραχυκύκλωμα, ελεύθερη κυκλοφορία, το ίζημα πέφτει στον πάτο."}, "status": "new"}, {"id": "L05-vent", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "The lead weight in a lead-acid vent plug:", "el": "Το βαρίδι μολύβδου στην τάπα εξαερισμού:"}, "o": [{"en": "closes the vent hole in inverted flight", "el": "κλείνει την οπή σε ανάποδη πτήση"}, {"en": "adds lead to the plates", "el": "προσθέτει μόλυβδο στις πλάκες"}, {"en": "measures the specific gravity", "el": "μετρά το ειδικό βάρος"}], "a": 0, "tags": [null, "vent_job", "vent_job"], "x": {"en": "Gas can escape in level flight; inverted, the weight covers the hole so no acid spills.", "el": "Σε οριζόντια πτήση τα αέρια βγαίνουν· ανάποδα, το βαρίδι κλείνει την οπή και δεν χύνεται οξύ."}, "status": "new"}, {"id": "L05-sump", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "The pad in the battery sump jar of a lead-acid installation is moistened with:", "el": "Το μαξιλαράκι στο δοχείο sump της εγκατάστασης μπαταρίας μολύβδου είναι εμποτισμένο με:"}, "o": [{"en": "sodium bicarbonate (baking soda) solution", "el": "διάλυμα διττανθρακικού νατρίου (σόδα)"}, {"en": "boric acid solution", "el": "διάλυμα βορικού οξέος"}, {"en": "distilled water", "el": "απεσταγμένο νερό"}], "a": 0, "tags": [null, "sump_mixup", "sump_water"], "x": {"en": "An alkali neutralizes the acid fumes. Boric acid (an acid) is used with alkaline nickel-cadmium batteries.", "el": "Μια αλκαλική ουσία εξουδετερώνει τους όξινους ατμούς. Το βορικό οξύ χρησιμοποιείται με τις αλκαλικές μπαταρίες νικελίου-καδμίου."}, "status": "new"}, {"id": "L05-discharge", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "As a lead-acid battery discharges, the specific gravity of the electrolyte:", "el": "Καθώς εκφορτίζεται μια μπαταρία μολύβδου, το ειδικό βάρος του ηλεκτρολύτη:"}, "o": [{"en": "rises", "el": "αυξάνεται"}, {"en": "falls", "el": "μειώνεται"}, {"en": "stays constant", "el": "μένει σταθερό"}], "a": 1, "tags": ["sg_direction", null, "sg_direction"], "x": {"en": "Acid is used up and water is formed, so the electrolyte becomes less dense.", "el": "Το οξύ καταναλώνεται και σχηματίζεται νερό, οπότε ο ηλεκτρολύτης αραιώνει."}, "status": "new"}, {"id": "L05-sulphate", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "When a lead-acid cell is discharged, both plates turn into:", "el": "Όταν εκφορτίζεται ένα στοιχείο μολύβδου, και οι δύο πλάκες γίνονται:"}, "o": [{"en": "lead sulphate", "el": "θειικός μόλυβδος"}, {"en": "lead dioxide", "el": "διοξείδιο του μολύβδου"}, {"en": "pure lead", "el": "καθαρός μόλυβδος"}], "a": 0, "tags": [null, "plate_swap", "plate_swap"], "x": {"en": "Sulphate ions join the lead in both plates: PbSO₄.", "el": "Τα θειικά ιόντα ενώνονται με τον μόλυβδο και στις δύο πλάκες: PbSO₄."}, "status": "new"}, {"id": "L05-cells24", "lesson": "L05", "topic": "3.05", "d": 1, "units": "—", "q": {"en": "A 24 V lead-acid battery has:", "el": "Μια μπαταρία μολύβδου 24 V έχει:"}, "o": [{"en": "6 cells in series", "el": "6 στοιχεία σε σειρά"}, {"en": "12 cells in series", "el": "12 στοιχεία σε σειρά"}, {"en": "24 cells in parallel", "el": "24 στοιχεία παράλληλα"}], "a": 1, "tags": ["cell_count", null, "series_parallel"], "x": {"en": "About 2 V per cell: 24 / 2 = 12 cells in series.", "el": "Περίπου 2 V ανά στοιχείο: 24 / 2 = 12 στοιχεία σε σειρά."}, "status": "new"}, {"id": "L05-Ah", "lesson": "L05", "topic": "3.05", "d": 2, "units": "SI", "q": {"en": "A 40 Ah battery should supply 8 A for about:", "el": "Μπαταρία 40 Ah μπορεί να δίνει 8 A για περίπου:"}, "o": [{"en": "5 h", "el": "5 h"}, {"en": "320 h", "el": "320 h"}, {"en": "0.2 h", "el": "0,2 h"}], "a": 0, "tags": [null, "multiplied", "inverted"], "x": {"en": "t = Ah / I = 40 / 8 = 5 h (in theory; heavy currents give less).", "el": "t = Ah / I = 40 / 8 = 5 h (θεωρητικά· με μεγάλα ρεύματα λιγότερο)."}, "status": "new"}, {"id": "L05-rating", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "The capacity of aircraft batteries is rated over a discharge time of:", "el": "Η χωρητικότητα των μπαταριών αεροσκαφών ορίζεται για χρόνο εκφόρτισης:"}, "o": [{"en": "1 hour", "el": "1 ώρας"}, {"en": "5 hours", "el": "5 ωρών"}, {"en": "24 hours", "el": "24 ωρών"}], "a": 1, "tags": ["rating_time", null, "rating_time"], "x": {"en": "The 5-hour rate is a basis for rating, not the time the battery will actually last.", "el": "Ο ρυθμός 5 ωρών είναι βάση για τη βαθμονόμηση, όχι ο πραγματικός χρόνος λειτουργίας."}, "status": "new"}, {"id": "L05-heavyI", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "Discharging a battery at a very high current:", "el": "Η εκφόρτιση μπαταρίας με πολύ μεγάλο ρεύμα:"}, "o": [{"en": "reduces the ampere-hours it can deliver", "el": "μειώνει τις αμπερώρες που μπορεί να δώσει"}, {"en": "increases its capacity", "el": "αυξάνει τη χωρητικότητά της"}, {"en": "has no effect on capacity", "el": "δεν επηρεάζει τη χωρητικότητα"}], "a": 0, "tags": [null, "capacity_rate", "capacity_rate"], "x": {"en": "Heavy current heats the battery and lowers its efficiency and total Ah output.", "el": "Το μεγάλο ρεύμα θερμαίνει την μπαταρία και μειώνει την απόδοση και τις συνολικές Ah."}, "status": "new"}, {"id": "L05-parallel", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "Two identical 24 V, 20 Ah batteries are connected in parallel. The result is:", "el": "Δύο ίδιες μπαταρίες 24 V, 20 Ah συνδέονται παράλληλα. Το αποτέλεσμα είναι:"}, "o": [{"en": "48 V, 20 Ah", "el": "48 V, 20 Ah"}, {"en": "24 V, 40 Ah", "el": "24 V, 40 Ah"}, {"en": "48 V, 40 Ah", "el": "48 V, 40 Ah"}], "a": 1, "tags": ["series_parallel", null, "series_parallel"], "x": {"en": "Parallel: same voltage, capacities add. Series: voltages add, same Ah.", "el": "Παράλληλα: ίδια τάση, οι χωρητικότητες προστίθενται. Σε σειρά: οι τάσεις προστίθενται, ίδιες Ah."}, "status": "new"}, {"id": "L05-series", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "Two 12 V, 30 Ah batteries are connected in series. The result is:", "el": "Δύο μπαταρίες 12 V, 30 Ah συνδέονται σε σειρά. Το αποτέλεσμα είναι:"}, "o": [{"en": "24 V, 30 Ah", "el": "24 V, 30 Ah"}, {"en": "12 V, 60 Ah", "el": "12 V, 60 Ah"}, {"en": "24 V, 60 Ah", "el": "24 V, 60 Ah"}], "a": 0, "tags": [null, "series_parallel", "series_parallel"], "x": {"en": "Series adds the voltages (24 V); the capacity stays 30 Ah.", "el": "Η σύνδεση σε σειρά προσθέτει τις τάσεις (24 V)· η χωρητικότητα μένει 30 Ah."}, "status": "new"}, {"id": "L05-cycle", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "Battery cycle life ends when capacity falls below:", "el": "Η διάρκεια ζωής σε κύκλους τελειώνει όταν η χωρητικότητα πέσει κάτω από:"}, "o": [{"en": "50% of rated capacity", "el": "50% της ονομαστικής χωρητικότητας"}, {"en": "80% of rated capacity", "el": "80% της ονομαστικής χωρητικότητας"}, {"en": "20% of rated capacity", "el": "20% της ονομαστικής χωρητικότητας"}], "a": 1, "tags": ["cycle_limit", null, "cycle_limit"], "x": {"en": "Cycle life = number of full cycles until capacity drops below 80% of rated (typically 500–1 300).", "el": "Κύκλοι ζωής = αριθμός πλήρων κύκλων μέχρι η χωρητικότητα να πέσει κάτω από 80% (συνήθως 500–1 300)."}, "status": "new"}, {"id": "L05-hydrometer", "lesson": "L05", "topic": "3.05", "d": 1, "units": "—", "q": {"en": "The state of charge of a lead-acid battery is checked with a:", "el": "Η κατάσταση φόρτισης μπαταρίας μολύβδου ελέγχεται με:"}, "o": [{"en": "hydrometer", "el": "υδρόμετρο (πυκνόμετρο)"}, {"en": "thermocouple", "el": "θερμοζεύγος"}, {"en": "megger", "el": "megger"}], "a": 0, "tags": [null, "source_mixup", "test_tool"], "x": {"en": "A hydrometer measures the specific gravity of the electrolyte.", "el": "Το υδρόμετρο μετρά το ειδικό βάρος του ηλεκτρολύτη."}, "status": "new"}, {"id": "L05-scale", "lesson": "L05", "topic": "3.05", "d": 3, "units": "—", "q": {"en": "On a battery hydrometer, the highest reading (1.300) is found:", "el": "Στο υδρόμετρο μπαταρίας, η μεγαλύτερη ένδειξη (1,300) βρίσκεται:"}, "o": [{"en": "at the top of the scale", "el": "στην κορυφή της κλίμακας"}, {"en": "at the bottom of the scale", "el": "στο κάτω μέρος της κλίμακας"}, {"en": "in the middle", "el": "στη μέση"}], "a": 1, "tags": ["float_scale", null, "float_scale"], "x": {"en": "Denser electrolyte makes the float ride higher, so the high values must be at the bottom of the stem.", "el": "Πυκνότερος ηλεκτρολύτης κάνει τον πλωτήρα να ανεβαίνει, άρα οι μεγάλες τιμές είναι στο κάτω μέρος του στελέχους."}, "status": "new"}, {"id": "L05-sgband", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "A hydrometer reading of 1.220 means the battery is:", "el": "Ένδειξη υδρομέτρου 1,220 σημαίνει ότι η μπαταρία είναι:"}, "o": [{"en": "in a high state of charge", "el": "σε υψηλή κατάσταση φόρτισης"}, {"en": "in a medium state of charge", "el": "σε μέση κατάσταση φόρτισης"}, {"en": "in a low state of charge and needs recharging", "el": "σε χαμηλή κατάσταση και χρειάζεται φόρτιση"}], "a": 2, "tags": ["sg_band", "sg_band", null], "x": {"en": "1.240–1.200 = low: recharge immediately.", "el": "1,240–1,200 = χαμηλή: άμεση φόρτιση."}, "status": "new"}, {"id": "L05-tempcorr", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "No temperature correction is needed for hydrometer readings between:", "el": "Δεν χρειάζεται διόρθωση θερμοκρασίας στις ενδείξεις υδρομέτρου μεταξύ:"}, "o": [{"en": "0 °C and 15 °C", "el": "0 °C και 15 °C"}, {"en": "21 °C and 32 °C", "el": "21 °C και 32 °C"}, {"en": "40 °C and 60 °C", "el": "40 °C και 60 °C"}], "a": 1, "tags": ["temp_range", null, "temp_range"], "x": {"en": "21–32 °C: no correction. Outside it, add or subtract the correction.", "el": "21–32 °C: καμία διόρθωση. Εκτός, προσθέτεις ή αφαιρείς τη διόρθωση."}, "status": "new"}, {"id": "L05-water", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "When should hydrometer readings be taken in relation to adding distilled water?", "el": "Πότε παίρνονται οι ενδείξεις υδρομέτρου σε σχέση με την προσθήκη απεσταγμένου νερού;"}, "o": [{"en": "before adding water, never after", "el": "πριν την προσθήκη νερού, ποτέ μετά"}, {"en": "immediately after adding water", "el": "αμέσως μετά την προσθήκη"}, {"en": "it does not matter", "el": "δεν έχει σημασία"}], "a": 0, "tags": [null, "water_timing", "water_timing"], "x": {"en": "Fresh water has not mixed yet: a sample after adding it would read too low.", "el": "Το νερό δεν έχει αναμειχθεί: δείγμα μετά την προσθήκη θα έδινε χαμηλή ένδειξη."}, "status": "new"}, {"id": "L05-acidskin", "lesson": "L05", "topic": "3.05", "d": 1, "units": "—", "q": {"en": "Lead-acid electrolyte splashed on the skin should be washed with water and then treated with:", "el": "Ηλεκτρολύτης μολύβδου στο δέρμα ξεπλένεται με νερό και μετά εξουδετερώνεται με:"}, "o": [{"en": "bicarbonate of soda", "el": "σόδα (διττανθρακικό νάτριο)"}, {"en": "vinegar", "el": "ξύδι"}, {"en": "more acid", "el": "περισσότερο οξύ"}], "a": 0, "tags": [null, "neutralizer", "neutralizer"], "x": {"en": "Acid is neutralized by an alkali (bicarbonate). Vinegar is used for the alkaline KOH of nickel-cadmium batteries.", "el": "Το οξύ εξουδετερώνεται με αλκαλικό (σόδα). Το ξύδι χρησιμοποιείται για το αλκαλικό KOH των μπαταριών νικελίου-καδμίου."}, "status": "new"}, {"id": "L05-rint", "lesson": "L05", "topic": "3.05", "d": 3, "units": "SI", "q": {"en": "A battery reads 25.2 V with no load and 24.0 V while supplying 40 A. Its internal resistance is:", "el": "Μια μπαταρία δείχνει 25,2 V χωρίς φορτίο και 24,0 V όταν δίνει 40 A. Η εσωτερική της αντίσταση είναι:"}, "o": [{"en": "0.03 Ω", "el": "0,03 Ω"}, {"en": "0.6 Ω", "el": "0,6 Ω"}, {"en": "1.2 Ω", "el": "1,2 Ω"}], "a": 0, "tags": [null, "rint_whole", "rint_drop"], "x": {"en": "r = (25.2 − 24.0) / 40 = 1.2 / 40 = 0.03 Ω.", "el": "r = (25,2 − 24,0) / 40 = 1,2 / 40 = 0,03 Ω."}, "status": "new"}, {"id": "L05-chargeV", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "The charging voltage of a battery must be:", "el": "Η τάση φόρτισης μιας μπαταρίας πρέπει να είναι:"}, "o": [{"en": "greater than its open-circuit voltage", "el": "μεγαλύτερη από την τάση ανοιχτού κυκλώματος"}, {"en": "equal to its open-circuit voltage", "el": "ίση με την τάση ανοιχτού κυκλώματος"}, {"en": "lower than its open-circuit voltage", "el": "μικρότερη από την τάση ανοιχτού κυκλώματος"}], "a": 0, "tags": [null, "charge_ir", "charge_ir"], "x": {"en": "V_charge = E + I × r: the charger must overcome the emf plus the internal voltage drop (e.g. 28 V for 26.4 V).", "el": "V_φόρτισης = E + I × r: ο φορτιστής ξεπερνά την ΗΕΔ και την εσωτερική πτώση τάσης (π.χ. 28 V για 26,4 V)."}, "status": "new"}, {"id": "L05-cvtaper", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "In constant-voltage charging, the charging current:", "el": "Στη φόρτιση σταθερής τάσης, το ρεύμα φόρτισης:"}, "o": [{"en": "starts high and tapers off as the battery charges", "el": "ξεκινά μεγάλο και μειώνεται καθώς φορτίζεται η μπαταρία"}, {"en": "stays constant", "el": "μένει σταθερό"}, {"en": "starts low and increases", "el": "ξεκινά μικρό και αυξάνεται"}], "a": 0, "tags": [null, "cv_cc", "cv_cc"], "x": {"en": "As the battery's emf rises, the difference to the fixed charger voltage falls, and so does the current (to ~1 A).", "el": "Καθώς ανεβαίνει η ΗΕΔ της μπαταρίας, μειώνεται η διαφορά από τη σταθερή τάση του φορτιστή, άρα και το ρεύμα (μέχρι ~1 A)."}, "status": "new"}, {"id": "L05-onboard", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "On the aircraft, the battery is charged by the generator using the:", "el": "Πάνω στο αεροσκάφος η μπαταρία φορτίζεται από τη γεννήτρια με τη μέθοδο:"}, "o": [{"en": "constant voltage method", "el": "σταθερής τάσης"}, {"en": "constant current method", "el": "σταθερού ρεύματος"}, {"en": "trickle discharge method", "el": "αργής εκφόρτισης"}], "a": 0, "tags": [null, "cv_cc", "cv_cc"], "x": {"en": "The voltage regulator holds the generator voltage constant.", "el": "Ο ρυθμιστής τάσης κρατά σταθερή την τάση της γεννήτριας."}, "status": "new"}, {"id": "L05-gas", "lesson": "L05", "topic": "3.05", "d": 2, "units": "—", "q": {"en": "While a lead-acid battery is being charged, the vent caps should be:", "el": "Κατά τη φόρτιση μπαταρίας μολύβδου, οι τάπες εξαερισμού πρέπει να:"}, "o": [{"en": "loosened but left in place", "el": "χαλαρώνονται αλλά μένουν στη θέση τους"}, {"en": "removed completely", "el": "αφαιρούνται εντελώς"}, {"en": "tightened fully", "el": "σφίγγονται καλά"}], "a": 0, "tags": [null, "vent_charge", "vent_charge"], "x": {"en": "Gas (hydrogen and oxygen) must escape, but the caps stay on to limit spray.", "el": "Τα αέρια (υδρογόνο και οξυγόνο) πρέπει να βγαίνουν, αλλά οι τάπες μένουν για να μη πετάγεται ηλεκτρολύτης."}, "status": "new"}]};
